// Auto-generated for the Unit Board — 學測易混淆字 形近字 (tools/confusables/build.py)
window.FA_DASHBOARD_UNITS = [{"unit":1,"theme":"quiet / quite / quit；aboard / abroad；cloth / clothe / clothes…","cards":[{"w":"quiet","p":"adj.","d":"making little or no noise","c":"安靜的","s":"Please keep quiet in the library because many students are studying for exams.","t":"請在圖書館保持安靜，因為很多學生在準備考試。"},{"w":"quite","p":"adv.","d":"very; fairly","c":"相當；十分","s":"The math test was quite difficult, but most of the class still passed it.","t":"數學考試相當難，但全班大部分人還是通過了。"},{"w":"quit","p":"v.","d":"to stop doing something; to leave a job","c":"停止；辭職","s":"My uncle quit smoking last year because his doctor warned him about his lungs.","t":"我叔叔去年戒菸了，因為醫生警告他肺部有問題。"},{"w":"aboard","p":"adv./prep.","d":"on or onto a ship, plane, or train","c":"在（交通工具）上","s":"All passengers must be aboard the ship thirty minutes before it leaves the harbor.","t":"所有乘客必須在船離港前三十分鐘登船。"},{"w":"abroad","p":"adv.","d":"in or to a foreign country","c":"在國外；到國外","s":"My cousin plans to study abroad in Germany after she graduates from senior high school.","t":"我表姊打算高中畢業後去德國留學。"},{"w":"cloth","p":"n.","d":"material made from cotton, wool, etc.","c":"布；布料","s":"Grandma cut the old cloth into small pieces and made a colorful blanket.","t":"奶奶把舊布剪成小塊，做成一條色彩繽紛的毯子。"},{"w":"clothe","p":"v.","d":"to provide clothes for someone","c":"給…穿衣；供給衣服","s":"The single mother worked two jobs to feed and clothe her three children.","t":"這位單親媽媽身兼兩份工作來養活三個孩子、供他們穿衣。"},{"w":"clothes","p":"n.","d":"things you wear, such as shirts and pants","c":"衣服","s":"Pack warm clothes for the trip, because it often snows in the mountains in January.","t":"旅行要帶保暖的衣服，因為一月山上常下雪。"},{"w":"loose","p":"adj.","d":"not tight or firmly fixed","c":"鬆的；寬鬆的","s":"One of the screws on my chair is loose, so it shakes when I sit down.","t":"我椅子上有顆螺絲鬆了，所以一坐下就搖晃。"},{"w":"lose","p":"v.","d":"to stop having something; to fail to win","c":"失去；遺失；輸","s":"If you lose your student ID card, you have to pay to get a new one.","t":"如果你遺失學生證，就得付費補辦一張新的。"},{"w":"vary","p":"v.","d":"to be different; to change","c":"不同；變化","s":"Prices of vegetables vary from season to season.","t":"蔬菜的價格隨季節而不同。"},{"w":"very","p":"adv.","d":"extremely","c":"非常","s":"The test was very easy, so everyone finished early.","t":"考試非常簡單，所以大家都提早寫完。"},{"w":"through","p":"prep.","d":"from one side or end to the other","c":"穿過；透過","s":"The train goes through a long tunnel under the mountain.","t":"火車穿過山下的一條長隧道。"},{"w":"though","p":"conj.","d":"although","c":"雖然","s":"Though it was raining hard, the game continued.","t":"雖然雨下得很大，比賽仍繼續進行。"},{"w":"thorough","p":"adj.","d":"complete and careful","c":"徹底的；仔細的","s":"The police made a thorough search of the house but found nothing.","t":"警方徹底搜查了房子，卻一無所獲。"},{"w":"tough","p":"adj.","d":"difficult; strong","c":"艱難的；堅韌的","s":"Losing his job was tough, but he never gave up looking for a new one.","t":"失業很難熬，但他從沒放棄找新工作。"},{"w":"flash","p":"n./v.","d":"a sudden bright light; to shine for a moment","c":"閃光；閃現","s":"A flash of lightning lit up the whole sky, and then we heard loud thunder.","t":"一道閃電照亮整片天空，接著我們聽到巨大的雷聲。"},{"w":"flesh","p":"n.","d":"the soft part of a body or fruit","c":"肉；果肉","s":"The flesh of this mango is sweet and soft, but the skin is a little bitter.","t":"這顆芒果的果肉香甜柔軟，但果皮有點苦。"},{"w":"fresh","p":"adj.","d":"new, recently made or picked","c":"新鮮的","s":"The restaurant uses fresh fish caught by local fishermen every morning.","t":"這家餐廳使用當地漁夫每天早上捕的新鮮魚。"},{"w":"angel","p":"n.","d":"a spirit from heaven; a very kind person","c":"天使；好心人","s":"The nurse was so gentle and patient that the children called her their angel.","t":"那位護理師溫柔又有耐心，孩子們都叫她天使。"},{"w":"angle","p":"n.","d":"the space between two lines that meet; a point of view","c":"角度；觀點","s":"If you look at the problem from a different angle, you may find an easier answer.","t":"如果你從不同的角度看這個問題，可能會找到更簡單的答案。"},{"w":"coarse","p":"adj.","d":"rough, not smooth or fine; rude","c":"粗糙的；粗俗的","s":"The beach is covered with coarse sand that hurts your feet if you walk without shoes.","t":"海灘上滿是粗沙，赤腳走會讓腳很痛。"},{"w":"course","p":"n.","d":"a class or set of lessons; a route","c":"課程；路線；過程","s":"She took an online course in photography during the summer vacation.","t":"她暑假上了一門線上攝影課程。"},{"w":"dairy","p":"n./adj.","d":"milk and food made from milk","c":"乳製品（的）；酪農場","s":"People who cannot digest milk well should avoid dairy products such as cheese and ice cream.","t":"無法消化牛奶的人應避免起司和冰淇淋等乳製品。"},{"w":"diary","p":"n.","d":"a book where you write about your day","c":"日記","s":"She has kept a diary since she was ten, writing a few lines before bed every night.","t":"她從十歲起寫日記，每晚睡前寫幾行。"}]},{"unit":2,"theme":"desert / dessert；mayor / major；route / root…","cards":[{"w":"desert","p":"n./v.","d":"a large dry area with sand; (v.) to leave someone who needs you","c":"沙漠；（v.）拋棄","s":"The travelers carried extra water because they had to cross the desert on foot.","t":"旅人多帶了水，因為他們必須徒步穿越沙漠。"},{"w":"dessert","p":"n.","d":"sweet food eaten at the end of a meal","c":"甜點","s":"We were too full after the steak, so we skipped dessert and just ordered tea.","t":"吃完牛排我們太飽了，所以跳過甜點只點了茶。"},{"w":"mayor","p":"n.","d":"the leader of a city or town","c":"市長；鎮長","s":"The mayor promised to build more bike lanes to reduce traffic in the city center.","t":"市長承諾增設自行車道以減少市中心的交通量。"},{"w":"major","p":"adj./n.","d":"very important; main subject at university","c":"主要的；主修","s":"Traffic is a major problem in big cities, especially during rush hour.","t":"交通是大城市的主要問題，尤其在尖峰時段。"},{"w":"route","p":"n.","d":"the way from one place to another","c":"路線；途徑","s":"The bus changed its route because the main road was closed.","t":"因主要道路封閉，公車改變了路線。"},{"w":"root","p":"n./v.","d":"the part of a plant under the soil; the cause","c":"根；根源","s":"Lack of sleep is often the root of poor concentration in class.","t":"睡眠不足常是上課無法專心的根源。"},{"w":"shallow","p":"adj.","d":"not deep; not serious in thinking","c":"淺的；膚淺的","s":"Young children should swim only in the shallow end of the pool.","t":"小孩只應在泳池淺水區游泳。"},{"w":"swallow","p":"v./n.","d":"to make food or drink go down your throat; a small bird","c":"吞嚥；燕子","s":"Cut the meat into small pieces so the baby can swallow it easily.","t":"把肉切小塊，讓寶寶容易吞嚥。"},{"w":"steal","p":"v.","d":"to take something that is not yours without permission","c":"偷竊","s":"Someone tried to steal my bike from outside the convenience store last night.","t":"昨晚有人想在便利商店外偷我的腳踏車。"},{"w":"steel","p":"n.","d":"a very strong metal made from iron","c":"鋼","s":"The new bridge is made of steel, so it can survive strong earthquakes.","t":"新橋是鋼造的，能承受強烈地震。"},{"w":"tailor","p":"n./v.","d":"a person who makes clothes; to make something for a special need","c":"裁縫；量身訂做","s":"The teacher tailored her lessons to meet the needs of slower learners.","t":"老師依照學習較慢學生的需求調整課程。"},{"w":"sailor","p":"n.","d":"a person who works on a ship","c":"水手；船員","s":"The old sailor told us stories about storms he had survived at sea.","t":"老水手跟我們說他在海上熬過暴風雨的故事。"},{"w":"wander","p":"v.","d":"to walk around without a clear direction","c":"閒逛；徘徊","s":"We wandered through the night market, trying different snacks.","t":"我們在夜市閒逛，嚐了各種小吃。"},{"w":"wonder","p":"v./n.","d":"to want to know; a feeling of surprise","c":"想知道；納悶；奇蹟","s":"I wonder why the bus is so late today.","t":"我在想今天公車為什麼這麼晚。"},{"w":"found","p":"v.","d":"to start an organization or company","c":"建立；創辦","s":"The school was founded in 1920 by a group of teachers from Tainan.","t":"這所學校是由一群台南的老師在 1920 年創辦的。"},{"w":"fund","p":"n./v.","d":"money saved or collected for a purpose; to pay for","c":"基金；資助","s":"The students sold cookies to raise funds for the animal shelter.","t":"學生們賣餅乾為動物收容所募款。"},{"w":"fond","p":"adj.","d":"liking someone or something","c":"喜愛的","s":"My grandfather is fond of old songs and often sings them while he cooks.","t":"我爺爺喜歡老歌，常常邊煮飯邊唱。"},{"w":"hanger","p":"n.","d":"a curved piece of wire or wood for hanging clothes","c":"衣架","s":"Please put your jacket on a hanger so it doesn't get wrinkled.","t":"請把外套掛在衣架上，才不會起皺。"},{"w":"hunger","p":"n.","d":"the feeling of needing food; a strong wish","c":"飢餓；渴望","s":"Millions of children around the world still suffer from hunger every day.","t":"全世界仍有數百萬兒童每天受飢餓之苦。"},{"w":"anger","p":"n.","d":"the strong feeling you have when you are upset","c":"憤怒","s":"He tried to hide his anger, but his red face showed how upset he really was.","t":"他試圖掩飾憤怒，但漲紅的臉顯示出他有多生氣。"},{"w":"scarce","p":"adj.","d":"not available in large amounts; hard to find","c":"稀少的；缺乏的","s":"Clean water becomes scarce in the village during the long dry season.","t":"漫長的乾季裡，村裡的乾淨水源變得稀少。"},{"w":"scare","p":"v./n.","d":"to make someone afraid","c":"驚嚇；使害怕","s":"The sudden noise from the kitchen scared the cat, and it ran under the bed.","t":"廚房突然傳來的聲響嚇到貓，牠跑到床底下。"},{"w":"scarf","p":"n.","d":"a long piece of cloth worn around the neck","c":"圍巾","s":"She wrapped a thick wool scarf around her neck before going out into the snow.","t":"她出門踏雪前把一條厚羊毛圍巾圍在脖子上。"}]},{"unit":3,"theme":"suite / suit / sweet；explode / explore；flee / flea / free…","cards":[{"w":"suite","p":"n.","d":"a set of rooms in a hotel; a set of music pieces","c":"套房；組曲","s":"The singer stayed in the largest suite on the top floor of the hotel.","t":"歌手住在飯店頂樓最大的套房。"},{"w":"suit","p":"n./v.","d":"a jacket with matching pants or skirt; to be right for someone","c":"套裝；西裝；適合","s":"The job suits her well because she loves talking to people.","t":"這份工作很適合她，因為她喜歡和人聊天。"},{"w":"sweet","p":"adj.","d":"tasting of sugar; kind","c":"甜的；貼心的","s":"It was sweet of you to remember my birthday.","t":"你記得我的生日，真貼心。"},{"w":"explode","p":"v.","d":"to burst with a loud noise; to suddenly increase","c":"爆炸；激增","s":"A gas tank exploded in the restaurant kitchen, but luckily no one was hurt.","t":"餐廳廚房的瓦斯桶爆炸了，幸好無人受傷。"},{"w":"explore","p":"v.","d":"to travel around a place to learn about it","c":"探索；探究","s":"We spent the whole afternoon exploring the old streets and small shops of Tainan.","t":"我們整個下午都在探索台南的老街和小店。"},{"w":"flee","p":"v.","d":"to run away from danger","c":"逃走；逃離","s":"Thousands of people had to flee their homes when the volcano began to erupt.","t":"火山開始噴發時，數千人不得不逃離家園。"},{"w":"flea","p":"n.","d":"a very small jumping insect that lives on animals","c":"跳蚤","s":"We gave our dog a bath with special soap because he was covered in fleas.","t":"我們用特殊肥皂幫狗洗澡，因為牠身上全是跳蚤。"},{"w":"free","p":"adj.","d":"costing nothing; able to do what you want","c":"免費的；自由的","s":"Children under six can enter the museum for free on weekends.","t":"週末六歲以下兒童可免費進入博物館。"},{"w":"habit","p":"n.","d":"something you do often and regularly","c":"習慣","s":"Reading before bed is a good habit that helps you relax.","t":"睡前閱讀是能幫你放鬆的好習慣。"},{"w":"habitat","p":"n.","d":"the natural home of an animal or plant","c":"棲息地","s":"Cutting down forests destroys the habitat of many birds.","t":"砍伐森林摧毀了許多鳥類的棲息地。"},{"w":"heir","p":"n.","d":"a person who will receive someone's money or property after they die","c":"繼承人","s":"As the only son, he is the heir to his father's company.","t":"身為獨子，他是父親公司的繼承人。"},{"w":"hair","p":"n.","d":"the thin threads that grow on your head","c":"頭髮；毛髮","s":"She cut her long hair short before the summer because the weather was so hot.","t":"天氣太熱，她入夏前把長髮剪短了。"},{"w":"loyal","p":"adj.","d":"always supporting a person, group, or idea","c":"忠誠的","s":"The small café survives because it has many loyal customers who come every day.","t":"這家小咖啡廳能存活下來，是因為有很多天天報到的忠實顧客。"},{"w":"royal","p":"adj.","d":"of or related to a king or queen","c":"皇家的；王室的","s":"Tourists line up in front of the palace to watch the royal guards change shifts.","t":"觀光客在宮殿前排隊觀看皇家衛兵換班。"},{"w":"merry","p":"adj.","d":"happy and cheerful","c":"歡樂的；愉快的","s":"The whole village sang merry songs and danced around the fire on New Year's Eve.","t":"除夕夜全村的人圍著火堆唱著歡樂的歌、跳舞。"},{"w":"marry","p":"v.","d":"to become someone's husband or wife","c":"結婚；嫁；娶","s":"They decided to marry next spring, after both of them finish graduate school.","t":"他們決定明年春天兩人都讀完研究所後結婚。"},{"w":"mercy","p":"n.","d":"kindness shown to someone you could punish","c":"慈悲；寬恕","s":"The prisoner begged the king for mercy and promised never to commit a crime again.","t":"囚犯向國王求饒，承諾再也不犯罪。"},{"w":"petty","p":"adj.","d":"small and unimportant; caring too much about small things","c":"瑣碎的；小氣的","s":"Don't let petty arguments ruin a long friendship.","t":"別讓瑣碎的爭吵毀了一段長久的友誼。"},{"w":"pretty","p":"adj./adv.","d":"attractive; fairly","c":"漂亮的；相當","s":"The test was pretty hard, but I think I passed.","t":"考試相當難，但我想我有過。"},{"w":"precious","p":"adj.","d":"very valuable or important","c":"珍貴的；寶貴的","s":"Time with your family is precious, so put down your phone at dinner.","t":"和家人相處的時間很珍貴，所以晚餐時放下手機吧。"},{"w":"previous","p":"adj.","d":"happening before","c":"先前的；以前的","s":"She has two years of previous experience working in a hotel.","t":"她有兩年在飯店工作的經驗。"},{"w":"soar","p":"v.","d":"to fly high; to rise quickly","c":"高飛；飆升","s":"Prices of eggs soared after the bird flu outbreak.","t":"禽流感爆發後，蛋價飆升。"},{"w":"sore","p":"adj.","d":"painful","c":"痠痛的；疼痛的","s":"My legs were sore after running ten kilometers.","t":"跑完十公里後我的腿很痠。"}]},{"unit":4,"theme":"sturdy / study；cite / site / sight；crude / cruel / rude…","cards":[{"w":"sturdy","p":"adj.","d":"strong and not easily broken","c":"堅固的；健壯的","s":"Buy a sturdy pair of boots for hiking.","t":"買一雙堅固的鞋子去健行。"},{"w":"study","p":"v./n.","d":"to learn about something","c":"讀書；研究","s":"She studies for two hours every night.","t":"她每晚讀書兩小時。"},{"w":"cite","p":"v.","d":"to mention words or facts as proof","c":"引用；舉出","s":"In your report, please cite at least two news articles to support your opinion.","t":"報告中請至少引用兩篇新聞報導來支持你的看法。"},{"w":"site","p":"n.","d":"a place where something is, was, or will be; a website","c":"地點；場址；網站","s":"Workers must wear helmets at all times at the building site.","t":"工人在建築工地必須隨時戴安全帽。"},{"w":"sight","p":"n.","d":"the ability to see; something you see","c":"視力；景象","s":"The sunset over the ocean was the most beautiful sight of our whole trip.","t":"海上的夕陽是我們整趟旅程中最美的景象。"},{"w":"crude","p":"adj.","d":"in a natural state; simple and not carefully made","c":"天然的；粗糙的；粗俗的","s":"The price of crude oil rose sharply last month.","t":"原油價格上個月大幅上漲。"},{"w":"cruel","p":"adj.","d":"causing pain or suffering on purpose","c":"殘忍的","s":"It is cruel to leave a dog tied up in the sun all day.","t":"把狗整天綁在大太陽下是很殘忍的。"},{"w":"rude","p":"adj.","d":"not polite","c":"無禮的；粗魯的","s":"It is rude to look at your phone while someone is talking to you.","t":"別人跟你說話時看手機很沒禮貌。"},{"w":"elect","p":"v.","d":"to choose someone by voting","c":"選舉；推選","s":"The students will elect a new class leader at the beginning of the semester.","t":"學期初學生會選出新的班長。"},{"w":"erect","p":"v./adj.","d":"to build or put up; standing straight","c":"豎立；建造；直立的","s":"The town erected a statue in the park to honor the brave firefighters.","t":"鎮上在公園豎立了一座雕像，紀念英勇的消防員。"},{"w":"select","p":"v.","d":"to choose carefully from a group","c":"挑選；選擇","s":"Only ten students were selected to join the national science camp this year.","t":"今年只有十名學生被選中參加全國科學營。"},{"w":"fright","p":"n.","d":"a sudden feeling of fear","c":"驚嚇；恐懼","s":"The loud bang gave the old woman such a fright that she dropped her cup.","t":"那聲巨響把老太太嚇得手中的杯子都掉了。"},{"w":"freight","p":"n.","d":"goods carried by ship, train, or plane","c":"貨物；貨運","s":"The freight train carries coal and steel from the port to factories in the south.","t":"這列貨運列車將煤和鋼從港口運到南部的工廠。"},{"w":"flight","p":"n.","d":"a trip by plane; the act of flying","c":"航班；飛行","s":"Our flight to Tokyo was delayed for three hours because of the typhoon.","t":"我們飛往東京的班機因颱風延誤了三小時。"},{"w":"genius","p":"n.","d":"a very intelligent or talented person","c":"天才；天賦","s":"Mozart was a musical genius who wrote songs when he was only five.","t":"莫札特是音樂天才，五歲就會作曲。"},{"w":"genuine","p":"adj.","d":"real; sincere","c":"真正的；真誠的","s":"Is this bag made of genuine leather or plastic?","t":"這個包包是真皮還是塑膠的？"},{"w":"generous","p":"adj.","d":"happy to give money, time, or help","c":"慷慨的；大方的","s":"Our generous neighbor often shares fruit from his garden.","t":"我們慷慨的鄰居常分享他園子裡的水果。"},{"w":"idle","p":"adj.","d":"not working or being used; lazy","c":"閒置的；懶散的","s":"The machines have been idle since the factory closed.","t":"工廠關閉後，機器一直閒置著。"},{"w":"idol","p":"n.","d":"a person who is greatly admired","c":"偶像","s":"The pop idol waved to thousands of screaming fans.","t":"這位流行偶像向數千名尖叫的粉絲揮手。"},{"w":"ideal","p":"adj./n.","d":"perfect; the best possible","c":"理想的；理想","s":"The weather was ideal for a picnic.","t":"這天氣很適合野餐。"},{"w":"medal","p":"n.","d":"a round piece of metal given as a prize","c":"獎牌；勳章","s":"The swimmer won a gold medal and became a national hero overnight.","t":"這位泳將贏得金牌，一夕之間成為國家英雄。"},{"w":"metal","p":"n.","d":"a hard material such as iron, gold, or copper","c":"金屬","s":"Aluminum is a light metal, so it is often used to make cans and airplanes.","t":"鋁是一種輕金屬，常用來製造罐子和飛機。"},{"w":"pedal","p":"n./v.","d":"the part you push with your foot to make a bike move","c":"踏板；踩踏板","s":"He pushed hard on the pedals to climb the steep hill on his bike.","t":"他用力踩踏板，騎著腳踏車爬上陡坡。"},{"w":"omit","p":"v.","d":"to leave out","c":"省略；遺漏","s":"You can omit the last question if you don't have time.","t":"如果沒時間，可以略過最後一題。"},{"w":"admit","p":"v.","d":"to agree that something bad is true; to allow to enter","c":"承認；准許進入","s":"He admitted that he had broken the window.","t":"他承認窗戶是他打破的。"},{"w":"submit","p":"v.","d":"to give in a document; to accept someone's power","c":"提交；屈服","s":"All reports must be submitted online by midnight.","t":"所有報告必須在午夜前線上繳交。"},{"w":"spit","p":"v.","d":"to force liquid or food out of your mouth","c":"吐（口水）；吐出","s":"It is rude and unhealthy to spit on the street.","t":"在街上吐痰既沒禮貌又不衛生。"},{"w":"spite","p":"n.","d":"a wish to hurt or annoy someone","c":"惡意；怨恨","s":"In spite of the heavy rain, thousands of fans waited outside the stadium.","t":"儘管下大雨，仍有數千名粉絲在體育場外等候。"},{"w":"split","p":"v.","d":"to divide into parts; to share","c":"分裂；分開；分攤","s":"Let's split the bill so that everyone pays the same amount.","t":"我們平分帳單，讓每個人付一樣的錢吧。"}]},{"unit":5,"theme":"temper / tempo / temple；chef / chief；confident / confidential…","cards":[{"w":"temper","p":"n.","d":"a tendency to get angry; mood","c":"脾氣；情緒","s":"He lost his temper and shouted at his little brother.","t":"他發脾氣對弟弟大吼。"},{"w":"tempo","p":"n.","d":"the speed of music or activity","c":"節奏；速度","s":"The song starts slowly, but the tempo picks up in the chorus.","t":"這首歌開頭很慢，但副歌節奏加快。"},{"w":"temple","p":"n.","d":"a building for worship; the flat side of the head","c":"廟宇；太陽穴","s":"We visited an old temple in Lukang.","t":"我們參觀了鹿港的一座古廟。"},{"w":"chef","p":"n.","d":"a professional cook","c":"主廚；廚師","s":"The chef uses only local vegetables in her dishes.","t":"這位主廚的料理只用在地蔬菜。"},{"w":"chief","p":"n./adj.","d":"the leader of a group; most important","c":"首長；主要的","s":"The fire chief told everyone to leave the building immediately.","t":"消防隊長要大家立刻離開大樓。"},{"w":"confident","p":"adj.","d":"feeling sure about yourself or something","c":"有信心的","s":"After practicing every day, she felt confident about the speech contest.","t":"每天練習後，她對演講比賽很有信心。"},{"w":"confidential","p":"adj.","d":"meant to be kept secret","c":"機密的","s":"Students' test scores are confidential and will not be posted online.","t":"學生的考試成績屬於機密，不會公布在網路上。"},{"w":"consist","p":"v.","d":"to be made of (consist of)","c":"由…組成","s":"The test consists of thirty multiple-choice questions and one essay.","t":"這份考試由三十題選擇題和一篇作文組成。"},{"w":"insist","p":"v.","d":"to say firmly that something must happen or is true","c":"堅持；堅稱","s":"My mother insisted on driving me to the station because it was raining.","t":"因為下雨，媽媽堅持開車送我去車站。"},{"w":"persist","p":"v.","d":"to continue doing or existing","c":"持續；堅持不懈","s":"If the pain persists for more than three days, see a doctor.","t":"如果疼痛持續超過三天，請就醫。"},{"w":"resist","p":"v.","d":"to fight against; to stop yourself from doing something","c":"抵抗；忍住","s":"I couldn't resist eating another piece of chocolate cake.","t":"我忍不住又吃了一塊巧克力蛋糕。"},{"w":"decay","p":"v./n.","d":"to rot or become gradually worse","c":"腐爛；衰退","s":"Eating too much candy can cause tooth decay.","t":"吃太多糖果會造成蛀牙。"},{"w":"delay","p":"v./n.","d":"to make something late; to put off","c":"延誤；延遲","s":"The train was delayed for an hour because of heavy snow.","t":"火車因大雪延誤了一小時。"},{"w":"hoarse","p":"adj.","d":"having a rough voice, often from shouting","c":"（聲音）沙啞的","s":"After cheering for three hours, my voice was hoarse.","t":"加油三小時後，我的聲音都啞了。"},{"w":"horse","p":"n.","d":"a large animal that people ride","c":"馬","s":"She has been riding horses since she was a child.","t":"她從小就開始騎馬。"},{"w":"lessen","p":"v.","d":"to make or become less","c":"減少；減輕","s":"Taking a short walk can lessen stress after a long day at work.","t":"散步一下能減輕長時間工作後的壓力。"},{"w":"lesson","p":"n.","d":"a class; something learned from experience","c":"課；教訓","s":"Failing the test taught me an important lesson: never leave review until the last night.","t":"考試不及格讓我學到一個重要教訓：別拖到最後一晚才複習。"},{"w":"mansion","p":"n.","d":"a very large and expensive house","c":"豪宅；宅邸","s":"The movie star lives in a mansion with ten bedrooms and a pool.","t":"那位電影明星住在一棟有十間臥室和泳池的豪宅。"},{"w":"mention","p":"v./n.","d":"to talk about something briefly","c":"提到；提及","s":"Did she mention when she would come back?","t":"她有提到什麼時候回來嗎？"},{"w":"massage","p":"n./v.","d":"rubbing someone's body to relax muscles","c":"按摩","s":"After the long hike, a foot massage helped me relax my tired legs.","t":"長途健行後，腳底按摩幫我放鬆疲憊的雙腿。"},{"w":"message","p":"n.","d":"a piece of written or spoken information","c":"訊息；留言","s":"I left a message on her phone, but she hasn't called me back yet.","t":"我在她手機上留言了，但她還沒回電。"},{"w":"personal","p":"adj.","d":"belonging to one person; private","c":"個人的；私人的","s":"Please don't ask me personal questions.","t":"請別問我私人問題。"},{"w":"personnel","p":"n.","d":"the people who work for an organization","c":"全體員工；人事部門","s":"Only medical personnel are allowed to enter this room.","t":"只有醫護人員可以進入這個房間。"}]},{"unit":6,"theme":"pleasant / peasant；premise / promise；prey / pray…","cards":[{"w":"pleasant","p":"adj.","d":"nice and enjoyable","c":"令人愉快的；宜人的","s":"We had a pleasant afternoon drinking tea by the lake.","t":"我們在湖邊喝茶，度過一個愉快的下午。"},{"w":"peasant","p":"n.","d":"a poor farmer who owns or rents a small piece of land","c":"農民；佃農","s":"In the past, most peasants worked on land that belonged to rich landlords.","t":"過去大多數農民在富有地主的土地上耕作。"},{"w":"premise","p":"n.","d":"an idea that an argument or plan is based on; (premises) a building and its land","c":"前提；（pl.）房屋及土地","s":"The story is based on the premise that animals can talk.","t":"這個故事的前提是動物會說話。"},{"w":"promise","p":"v./n.","d":"to say that you will certainly do something","c":"承諾；答應","s":"He promised to call me as soon as he arrived.","t":"他答應一到就打電話給我。"},{"w":"prey","p":"n./v.","d":"an animal that is hunted by another; to hunt","c":"獵物；捕食","s":"The eagle circled high above the field, looking for prey.","t":"老鷹在田野上空盤旋，尋找獵物。"},{"w":"pray","p":"v.","d":"to speak to God; to hope very much","c":"祈禱；祈求","s":"The farmers prayed for rain after three months of dry weather.","t":"經過三個月的乾旱，農民們祈求下雨。"},{"w":"racial","p":"adj.","d":"related to a person's race","c":"種族的","s":"The school has strict rules against racial jokes and bullying.","t":"學校嚴格禁止種族笑話和霸凌。"},{"w":"facial","p":"adj./n.","d":"related to the face; a beauty treatment for the face","c":"臉部的；臉部保養","s":"Her facial expression changed when she heard the bad news.","t":"她聽到壞消息時表情變了。"},{"w":"retail","p":"n./adj.","d":"the sale of goods to the public in small amounts","c":"零售","s":"She works as a manager in a large retail store.","t":"她在一家大型零售店擔任經理。"},{"w":"detail","p":"n.","d":"a small fact or piece of information","c":"細節","s":"Please tell me every detail of what happened.","t":"請告訴我事情的每個細節。"},{"w":"sacred","p":"adj.","d":"holy; very important","c":"神聖的","s":"The mountain is sacred to the local tribe, so visitors must not climb it.","t":"這座山對當地部落來說是神聖的，因此遊客不得攀登。"},{"w":"scared","p":"adj.","d":"afraid","c":"害怕的","s":"My little sister is scared of the dark, so she sleeps with a light on.","t":"我妹妹怕黑，所以開著燈睡覺。"},{"w":"sole","p":"adj./n.","d":"only; the bottom of a foot or shoe","c":"唯一的；鞋底","s":"She was the sole survivor of the plane crash.","t":"她是那場空難中唯一的倖存者。"},{"w":"soul","p":"n.","d":"the spirit of a person","c":"靈魂；心靈","s":"Music is food for the soul.","t":"音樂是心靈的食糧。"},{"w":"stake","p":"n.","d":"a post in the ground; money or something risked","c":"樁；賭注；利害關係","s":"With the championship at stake, both teams played their best.","t":"冠軍就在此一舉，兩隊都全力以赴。"},{"w":"steak","p":"n.","d":"a thick slice of beef or fish","c":"牛排；肉排","s":"How would you like your steak, medium or well-done?","t":"您的牛排要幾分熟，五分還是全熟？"},{"w":"strait","p":"n.","d":"a narrow area of sea between two pieces of land","c":"海峽","s":"Ships sail through the Taiwan Strait every day.","t":"每天都有船隻航經台灣海峽。"},{"w":"straight","p":"adj./adv.","d":"not bent or curved; directly","c":"直的；直接","s":"Go straight for two blocks, and the bank is on your left.","t":"直走兩個路口，銀行就在你左手邊。"},{"w":"thrust","p":"v./n.","d":"to push suddenly and strongly; the main point","c":"猛推；要點","s":"He thrust the letter into my hand and ran away.","t":"他把信塞到我手裡就跑了。"},{"w":"trust","p":"v./n.","d":"to believe that someone is honest","c":"信任","s":"I trust her because she always keeps her promises.","t":"我信任她，因為她總是信守承諾。"}]},{"unit":7,"theme":"tropic / topic；widow / window；clash / crash / crush…","cards":[{"w":"tropic","p":"n.","d":"one of two lines around the earth; (the tropics) hot area","c":"回歸線；熱帶地區","s":"The Tropic of Cancer passes through Chiayi in Taiwan.","t":"北回歸線通過台灣嘉義。"},{"w":"topic","p":"n.","d":"a subject of discussion","c":"主題；話題","s":"The topic of today's essay is \"My Hometown.\"","t":"今天作文的題目是「我的家鄉」。"},{"w":"widow","p":"n.","d":"a woman whose husband has died","c":"寡婦","s":"After her husband died, the widow ran the small farm by herself.","t":"丈夫過世後，這位寡婦獨自經營小農場。"},{"w":"window","p":"n.","d":"an opening in a wall with glass","c":"窗戶","s":"Please close the window; it's getting cold in here.","t":"請把窗戶關上，這裡越來越冷了。"},{"w":"clash","p":"n./v.","d":"a fight or strong disagreement; to happen at the same time","c":"衝突；（時間）撞期","s":"The two concerts clash, so I can only go to one of them.","t":"兩場演唱會撞期，所以我只能去一場。"},{"w":"crash","p":"n./v.","d":"a violent accident; to hit something hard","c":"撞擊；墜毀；（電腦）當機","s":"My computer crashed just before I could save my report.","t":"我還來不及存檔，電腦就當機了。"},{"w":"crush","p":"v./n.","d":"to press hard and break; a strong liking for someone","c":"壓碎；迷戀","s":"Crush the garlic before you add it to the soup.","t":"加入湯前先把大蒜壓碎。"},{"w":"exert","p":"v.","d":"to use power, effort, or influence","c":"施加；運用（力量）","s":"Parents exert a strong influence on their children's habits.","t":"父母對孩子的習慣有很大的影響力。"},{"w":"expert","p":"n./adj.","d":"a person with special knowledge or skill","c":"專家","s":"An expert from the museum checked whether the old painting was real.","t":"博物館的專家鑑定那幅舊畫是否為真跡。"},{"w":"export","p":"v./n.","d":"to sell goods to another country","c":"出口；輸出","s":"Taiwan exports computer chips to countries all over the world.","t":"台灣將電腦晶片出口到世界各國。"},{"w":"humor","p":"n.","d":"the quality of being funny","c":"幽默","s":"Our history teacher has a great sense of humor, so nobody falls asleep in her class.","t":"我們歷史老師很有幽默感，所以上她的課沒人會睡著。"},{"w":"rumor","p":"n.","d":"a story people pass on that may not be true","c":"謠言；傳聞","s":"There is a rumor that the school will cancel the sports day, but nobody knows if it's true.","t":"有傳言說學校會取消運動會，但沒人知道是不是真的。"},{"w":"tumor","p":"n.","d":"a mass of cells growing in the body where it should not","c":"腫瘤","s":"The doctors removed the tumor, and the patient is now recovering well.","t":"醫生切除了腫瘤，病人現在恢復良好。"},{"w":"mist","p":"n.","d":"thin fog; tiny drops of water in the air","c":"薄霧","s":"Early in the morning, a light mist covered the lake and the mountains.","t":"清晨，一層薄霧籠罩著湖面和群山。"},{"w":"moist","p":"adj.","d":"slightly wet","c":"潮濕的；濕潤的","s":"Keep the soil moist, but don't give the plant too much water.","t":"保持土壤濕潤，但別給植物太多水。"},{"w":"midst","p":"n.","d":"the middle of something","c":"中間；當中","s":"In the midst of the exam, the lights suddenly went out.","t":"考試考到一半，燈突然熄了。"},{"w":"relay","p":"n./v.","d":"a race in teams; to pass on a message","c":"接力賽；轉達","s":"Our class won the 400-meter relay on sports day.","t":"我們班在運動會贏得四百公尺接力。"},{"w":"rely","p":"v.","d":"to depend on someone or something","c":"依賴；信賴","s":"Many farmers rely on rain to water their fields.","t":"許多農民依靠雨水灌溉田地。"},{"w":"reply","p":"v./n.","d":"to answer","c":"回覆；回答","s":"Please reply to my e-mail before Friday.","t":"請在週五前回覆我的電子郵件。"},{"w":"reserve","p":"v./n.","d":"to book in advance; to keep for later use","c":"預訂；保留；儲備","s":"We reserved a table for eight at the seafood restaurant.","t":"我們在海鮮餐廳訂了一張八人桌。"},{"w":"preserve","p":"v.","d":"to keep something safe or in good condition","c":"保存；保護","s":"The old town works hard to preserve its traditional buildings.","t":"這座古城努力保存傳統建築。"},{"w":"deserve","p":"v.","d":"to have earned something because of what you did","c":"應得；值得","s":"You worked hard all year, so you deserve a long holiday.","t":"你努力工作了一整年，應該好好放個長假。"},{"w":"stumble","p":"v.","d":"to almost fall after hitting your foot on something","c":"絆倒；蹣跚","s":"I stumbled over a stone in the dark.","t":"我在黑暗中被石頭絆了一下。"},{"w":"tumble","p":"v.","d":"to fall down suddenly; to drop quickly","c":"跌倒；滾落；暴跌","s":"Stock prices tumbled after the bad news.","t":"壞消息傳出後股價暴跌。"},{"w":"humble","p":"adj.","d":"not proud; simple","c":"謙虛的；卑微的","s":"Despite his fame, the actor remains humble and friendly.","t":"儘管出名，這位演員仍謙虛友善。"},{"w":"trait","p":"n.","d":"a particular quality of a person","c":"特質；特點","s":"Honesty is her best trait.","t":"誠實是她最好的特質。"},{"w":"traitor","p":"n.","d":"a person who betrays their country or friends","c":"叛徒；賣國賊","s":"He was called a traitor for selling secrets to the enemy.","t":"他因出賣機密給敵人而被稱為叛徒。"},{"w":"treat","p":"v./n.","d":"to behave toward someone; to pay for someone","c":"對待；請客；治療","s":"Let me treat you to lunch today.","t":"今天我請你吃午餐。"}]},{"unit":8,"theme":"adapt / adopt；breath / breathe / breadth；carton / cartoon…","cards":[{"w":"adapt","p":"v.","d":"to change in order to fit a new situation","c":"適應；改編","s":"It took the exchange student a few months to adapt to the cold winters in Canada.","t":"這位交換學生花了幾個月才適應加拿大寒冷的冬天。"},{"w":"adopt","p":"v.","d":"to start using an idea or method; to take a child into your family","c":"採用；領養","s":"After the flood, the town adopted a new plan to protect homes near the river.","t":"水災過後，鎮上採用了一套保護河邊住家的新計畫。"},{"w":"breath","p":"n.","d":"the air you take into and let out of your lungs","c":"呼吸；一口氣","s":"Take a deep breath and count to ten before you answer an angry customer.","t":"回應生氣的顧客前，先深吸一口氣並數到十。"},{"w":"breathe","p":"v.","d":"to take air into your lungs and let it out","c":"呼吸","s":"It was hard to breathe at the top of the mountain because the air was so thin.","t":"在山頂上很難呼吸，因為空氣非常稀薄。"},{"w":"breadth","p":"n.","d":"the distance from one side to the other; wide range","c":"寬度；廣度","s":"The teacher was impressed by the breadth of her reading, from history to science fiction.","t":"老師對她閱讀的廣度印象深刻，從歷史到科幻小說都有。"},{"w":"carton","p":"n.","d":"a cardboard or paper box for food or drinks","c":"紙盒；紙箱","s":"I bought a carton of milk and a dozen eggs on the way home from school.","t":"我放學回家途中買了一盒牛奶和一打雞蛋。"},{"w":"cartoon","p":"n.","d":"a funny drawing; an animated film","c":"卡通；漫畫","s":"My little brother watches a cartoon about talking animals every Saturday morning.","t":"我弟弟每週六早上都看一部關於會說話動物的卡通。"},{"w":"cease","p":"v.","d":"to stop","c":"停止；終止","s":"The factory ceased production after it lost its biggest customer.","t":"這家工廠失去最大客戶後停止生產。"},{"w":"seize","p":"v.","d":"to take hold of suddenly; to take by force","c":"抓住；奪取；把握","s":"You should seize every chance to practice speaking English.","t":"你應把握每個練習說英文的機會。"},{"w":"civic","p":"adj.","d":"related to a city or the duties of citizens","c":"市民的；公民的","s":"Voting is an important civic duty for every adult.","t":"投票是每個成年人重要的公民義務。"},{"w":"civil","p":"adj.","d":"related to ordinary citizens; polite","c":"公民的；民間的；有禮的","s":"The country was badly damaged after ten years of civil war.","t":"這個國家經過十年內戰後受到嚴重破壞。"},{"w":"civilian","p":"n./adj.","d":"a person who is not in the army or police","c":"平民；百姓","s":"Many civilians lost their homes during the bombing.","t":"許多平民在轟炸中失去家園。"},{"w":"confirm","p":"v.","d":"to say or show that something is true or will happen","c":"確認；證實","s":"Please call the hotel to confirm our booking before we leave for the airport.","t":"出發去機場前請打電話向飯店確認訂房。"},{"w":"conform","p":"v.","d":"to obey rules or behave like other people","c":"遵守；順從","s":"All new buildings must conform to the safety rules for earthquakes.","t":"所有新建築都必須符合防震安全規定。"},{"w":"contemporary","p":"adj./n.","d":"belonging to the present time; living at the same time","c":"當代的；同時代的（人）","s":"The museum has a special exhibition of contemporary art from Asia.","t":"博物館有一場亞洲當代藝術特展。"},{"w":"temporary","p":"adj.","d":"lasting for only a short time","c":"暫時的；臨時的","s":"He found a temporary job at a bookstore during the winter vacation.","t":"他寒假在書店找到一份臨時工作。"},{"w":"contest","p":"n.","d":"a competition","c":"比賽；競賽","s":"She won first prize in the English speech contest held by the city government.","t":"她在市政府舉辦的英語演講比賽中獲得第一名。"},{"w":"context","p":"n.","d":"the words or situation around something that help explain it","c":"上下文；背景","s":"If you do not know a word, try to guess its meaning from the context.","t":"遇到不會的字，試著從上下文猜它的意思。"},{"w":"contract","p":"n./v.","d":"a legal agreement; to become smaller","c":"合約；收縮","s":"The singer signed a five-year contract with a record company.","t":"這位歌手和唱片公司簽了五年合約。"},{"w":"contrast","p":"n./v.","d":"a clear difference between two things","c":"對比；對照","s":"There is a sharp contrast between the busy city and the quiet village.","t":"熱鬧的城市和寧靜的村莊形成強烈對比。"},{"w":"contradict","p":"v.","d":"to say the opposite; to disagree with facts","c":"反駁；與…矛盾","s":"His actions contradict what he says about protecting the environment.","t":"他的行為和他宣稱保護環境的話互相矛盾。"},{"w":"emerge","p":"v.","d":"to come out from somewhere; to become known","c":"浮現；出現","s":"The sun emerged from behind the clouds just as the game started.","t":"比賽剛開始時，太陽從雲後露了出來。"},{"w":"merge","p":"v.","d":"to join together into one","c":"合併；融合","s":"The two small banks merged to form one large bank.","t":"兩家小銀行合併成一家大銀行。"},{"w":"emergency","p":"n.","d":"a sudden dangerous situation that needs quick action","c":"緊急情況","s":"In an emergency, call 119 for an ambulance.","t":"緊急時請撥 119 叫救護車。"}]},{"unit":9,"theme":"expedition / exhibition；haunt / hunt；heroin / heroine…","cards":[{"w":"expedition","p":"n.","d":"a long trip for a special purpose, such as exploring","c":"探險；遠征","s":"The team went on an expedition to study penguins in Antarctica.","t":"這個團隊遠征南極研究企鵝。"},{"w":"exhibition","p":"n.","d":"a public show of art or objects","c":"展覽","s":"The art exhibition attracted more than ten thousand visitors.","t":"這場藝術展吸引了一萬多名參觀者。"},{"w":"haunt","p":"v.","d":"to appear as a ghost; to keep troubling someone's mind","c":"（鬼）出沒；縈繞","s":"People say the old house is haunted by the ghost of a sad woman.","t":"人們說那棟老屋有一個悲傷女子的鬼魂出沒。"},{"w":"hunt","p":"v./n.","d":"to chase and kill animals; to search for","c":"打獵；搜尋","s":"My cousin is hunting for an apartment near her new office.","t":"我表姊正在新辦公室附近找公寓。"},{"w":"heroin","p":"n.","d":"a strong illegal drug","c":"海洛因","s":"The police found a large amount of heroin hidden in the ship.","t":"警方在船上發現藏有大量海洛因。"},{"w":"heroine","p":"n.","d":"a woman admired for bravery; the main female character","c":"女英雄；女主角","s":"The heroine of the novel is a young girl who saves her village from a flood.","t":"這部小說的女主角是一位從水災中拯救村莊的少女。"},{"w":"hostel","p":"n.","d":"a cheap place to stay, often for young travelers","c":"青年旅館","s":"We stayed in a youth hostel to save money during our trip to Europe.","t":"為了省錢，我們歐洲旅行時住青年旅館。"},{"w":"hostile","p":"adj.","d":"very unfriendly; showing a wish to fight","c":"有敵意的；不友善的","s":"The new student felt the class was hostile, but it was only because they were shy.","t":"新同學覺得班上對他不友善，其實只是大家害羞。"},{"w":"hotel","p":"n.","d":"a building where people pay to stay","c":"飯店；旅館","s":"The hotel is next to the train station, which is very convenient.","t":"這家飯店在火車站旁邊，非常方便。"},{"w":"inferior","p":"adj.","d":"not as good as someone or something else","c":"較差的；低等的","s":"These cheap shoes are inferior to the brand-name ones, but they are fine for daily use.","t":"這雙便宜的鞋比名牌差，但日常穿還可以。"},{"w":"interior","p":"n./adj.","d":"the inside part of something","c":"內部（的）；室內","s":"The outside of the house looks old, but the interior has been completely redesigned.","t":"這棟房子外觀看起來很舊，但室內已經全部重新設計過。"},{"w":"inquire","p":"v.","d":"to ask for information","c":"詢問；調查","s":"I called the hotel to inquire about rooms for the holiday.","t":"我打電話到飯店詢問假期的房間。"},{"w":"acquire","p":"v.","d":"to get or learn something","c":"獲得；習得","s":"Children acquire language naturally by listening and talking.","t":"孩子透過聽和說自然地習得語言。"},{"w":"require","p":"v.","d":"to need; to make someone do something by law","c":"需要；要求","s":"All visitors are required to show an ID card.","t":"所有訪客都必須出示身分證。"},{"w":"invent","p":"v.","d":"to create something that did not exist before","c":"發明；捏造","s":"Thomas Edison did not invent the first light bulb, but he made it practical for homes.","t":"愛迪生並未發明第一顆燈泡，但他讓燈泡能實用於家庭。"},{"w":"invest","p":"v.","d":"to put money or time into something to get a benefit","c":"投資；投入","s":"My parents invested most of their savings in a small apartment near the MRT station.","t":"我爸媽把大部分積蓄投資在捷運站附近的一間小公寓。"},{"w":"intent","p":"n./adj.","d":"purpose; (adj.) very focused","c":"意圖；（adj.）專注的","s":"The man was charged with entering the building with intent to steal.","t":"這名男子被控意圖行竊而進入大樓。"},{"w":"native","p":"adj./n.","d":"born in a place; a person born in a place","c":"本地的；土生的；本地人","s":"Her native language is Japanese, but she speaks English and Chinese fluently.","t":"她的母語是日語，但英語和中文都說得很流利。"},{"w":"naive","p":"adj.","d":"too ready to believe others because of little experience","c":"天真的；幼稚的","s":"It was naive of him to believe that the cheap phone online was a real brand-name one.","t":"他相信網路上那支便宜手機是正牌貨，真是太天真了。"},{"w":"patron","p":"n.","d":"a person who supports an artist or is a regular customer","c":"贊助者；老主顧","s":"The café gives free cake to its regular patrons on their birthdays.","t":"這家咖啡廳會在老主顧生日時送免費蛋糕。"},{"w":"pattern","p":"n.","d":"a repeated design; a regular way something happens","c":"花紋；模式","s":"Scientists studied the sleep patterns of teenagers.","t":"科學家研究青少年的睡眠模式。"},{"w":"patrol","p":"v./n.","d":"to walk or drive around an area to guard it","c":"巡邏","s":"Police officers patrol the night market every evening.","t":"警察每晚巡邏夜市。"},{"w":"prophet","p":"n.","d":"a person who tells what will happen in the future","c":"先知；預言家","s":"In the story, the prophet warned the king about a terrible flood.","t":"故事中，先知警告國王將有一場可怕的洪水。"},{"w":"profit","p":"n./v.","d":"money you earn after paying costs","c":"利潤；獲利","s":"The small shop made a profit of fifty thousand dollars last year.","t":"這家小店去年獲利五萬元。"}]},{"unit":10,"theme":"quote / quota；recipe / receipt / recipient；resemble / assemble…","cards":[{"w":"quote","p":"v./n.","d":"to repeat someone's exact words","c":"引用；引述","s":"The reporter quoted the mayor's words in the first line of the article.","t":"記者在文章第一行引用了市長的話。"},{"w":"quota","p":"n.","d":"a fixed number or amount that is allowed or needed","c":"配額；限額","s":"Each factory has a quota for how much pollution it can produce each year.","t":"每家工廠每年的污染排放量都有限額。"},{"w":"recipe","p":"n.","d":"instructions for cooking a dish","c":"食譜；秘訣","s":"My grandmother's recipe for beef noodles is a family secret.","t":"奶奶的牛肉麵食譜是家族秘方。"},{"w":"receipt","p":"n.","d":"a paper that shows you have paid","c":"收據；發票","s":"Keep the receipt in case you need to return the shoes.","t":"保留收據，以防你需要退回鞋子。"},{"w":"recipient","p":"n.","d":"a person who receives something","c":"接受者；得獎人","s":"She was the youngest recipient of the national science award.","t":"她是全國科學獎最年輕的得主。"},{"w":"resemble","p":"v.","d":"to look like or be similar to","c":"相像；類似","s":"She closely resembles her mother, especially when she smiles.","t":"她長得很像媽媽，尤其笑起來時。"},{"w":"assemble","p":"v.","d":"to gather in one place; to put parts together","c":"集合；組裝","s":"All students must assemble on the playground at eight o'clock.","t":"所有學生八點必須在操場集合。"},{"w":"revise","p":"v.","d":"to change and improve something you wrote","c":"修改；修訂","s":"Please revise your essay and fix the grammar mistakes.","t":"請修改你的作文並訂正文法錯誤。"},{"w":"revive","p":"v.","d":"to bring back to life or make popular again","c":"復甦；使復興","s":"The town is trying to revive its old tea industry.","t":"這個小鎮正努力復興當地傳統的製茶業。"},{"w":"review","p":"v./n.","d":"to look at again; a report giving an opinion","c":"複習；檢討；評論","s":"Let's review the last chapter before the test.","t":"考試前我們來複習最後一章吧。"},{"w":"scatter","p":"v.","d":"to throw or spread things in many directions","c":"撒；散布；四散","s":"The farmer scattered seeds across the field before the spring rain.","t":"農夫在春雨來臨前把種子撒遍田地。"},{"w":"shatter","p":"v.","d":"to break suddenly into many small pieces; to destroy","c":"粉碎；使破滅","s":"The window shattered when the baseball hit it, and glass flew everywhere.","t":"棒球打中窗戶時玻璃碎裂，碎片四處飛散。"},{"w":"serial","p":"adj./n.","d":"happening one after another; a story told in parts","c":"連續的；連續劇","s":"Check the serial number on the back of your phone.","t":"檢查你手機背面的序號。"},{"w":"cereal","p":"n.","d":"breakfast food made from grain","c":"穀片；穀類","s":"I eat a bowl of cereal with milk every morning.","t":"我每天早上吃一碗穀片加牛奶。"},{"w":"shove","p":"v.","d":"to push roughly","c":"推擠；猛推","s":"People shoved each other to get on the crowded train.","t":"人們推擠著擠上擁擠的火車。"},{"w":"shovel","p":"n./v.","d":"a tool for digging and moving earth or snow","c":"鏟子；鏟","s":"We used a shovel to clear the snow from the front door.","t":"我們用鏟子把門前的雪清掉。"},{"w":"steer","p":"v.","d":"to control the direction of a vehicle or a situation","c":"駕駛；引導","s":"The teacher steered the discussion back to the main topic.","t":"老師把討論引導回主題。"},{"w":"stir","p":"v.","d":"to mix with a spoon; to cause strong feelings","c":"攪拌；激起","s":"Stir the soup slowly so it doesn't burn.","t":"慢慢攪拌湯，才不會燒焦。"},{"w":"stink","p":"v./n.","d":"to have a very bad smell","c":"發臭；惡臭","s":"The garbage stinks; please take it out now.","t":"垃圾好臭，請現在拿出去倒。"},{"w":"sting","p":"v./n.","d":"to hurt with a sharp point, like a bee","c":"叮；刺痛","s":"Bees usually sting only when they feel their nest is in danger.","t":"蜜蜂通常只在覺得蜂巢有危險時才會螫人。"},{"w":"superb","p":"adj.","d":"excellent","c":"極好的；一流的","s":"The hotel offers a superb view of the ocean.","t":"這家飯店有絕佳的海景。"},{"w":"suburb","p":"n.","d":"an area where people live outside the center of a city","c":"郊區","s":"Many families move to the suburbs for bigger houses.","t":"許多家庭搬到郊區住更大的房子。"}]},{"unit":11,"theme":"vacation / vocation；venue / avenue；efficient / sufficient / proficient…","cards":[{"w":"vacation","p":"n.","d":"a time of rest from work or school","c":"假期","s":"We spent our summer vacation hiking and camping in Hualien.","t":"我們暑假在花蓮健行露營。"},{"w":"vocation","p":"n.","d":"a job you feel strongly suited for","c":"職業；使命感；天職","s":"Teaching is not just a job for her; it is a true vocation.","t":"教書對她而言不只是工作，而是真正的天職。"},{"w":"venue","p":"n.","d":"the place where an event happens","c":"場地；會場","s":"The venue for the concert was changed because of the rain.","t":"演唱會的場地因下雨而更改。"},{"w":"avenue","p":"n.","d":"a wide street; a way to achieve something","c":"大街；途徑","s":"There are many restaurants along this avenue.","t":"這條大街上有很多餐廳。"},{"w":"efficient","p":"adj.","d":"working well without wasting time or energy","c":"有效率的","s":"The new train system is fast and efficient.","t":"新的火車系統快速又有效率。"},{"w":"sufficient","p":"adj.","d":"enough","c":"足夠的","s":"We don't have sufficient money to buy a new car this year.","t":"我們今年沒有足夠的錢買新車。"},{"w":"proficient","p":"adj.","d":"skilled at doing something","c":"精通的；熟練的","s":"She is proficient in three languages: Chinese, English, and Japanese.","t":"她精通中、英、日三種語言。"},{"w":"scent","p":"n.","d":"a pleasant smell","c":"香味；氣味","s":"The scent of fresh bread came from the bakery across the street.","t":"對街麵包店飄來新鮮麵包的香味。"},{"w":"cent","p":"n.","d":"one hundredth of a dollar","c":"分（貨幣單位）","s":"The candy costs ninety-nine cents, so I gave the cashier a dollar.","t":"這顆糖要九十九分，所以我給了收銀員一美元。"},{"w":"sent","p":"v.","d":"past tense of send","c":"寄出；送出（send 的過去式）","s":"I sent the package last Monday, but it still hasn't arrived.","t":"我上週一就寄出包裹了，但它還沒到。"},{"w":"assume","p":"v.","d":"to think something is true without proof; to take on a role","c":"假定；承擔","s":"Don't assume that everyone knows the rules; explain them clearly.","t":"別以為每個人都知道規則，要清楚說明。"},{"w":"presume","p":"v.","d":"to believe something is likely without being sure","c":"推定；認為","s":"The missing hikers are presumed to be safe because they had enough food.","t":"失蹤的登山客被推定平安，因為他們帶了足夠的食物。"},{"w":"resume","p":"v.","d":"to start again after a pause","c":"重新開始；恢復","s":"The game will resume as soon as the rain stops.","t":"雨一停，比賽就會恢復進行。"},{"w":"consume","p":"v.","d":"to use up; to eat or drink","c":"消耗；吃喝","s":"Old air conditioners consume a lot of electricity.","t":"舊冷氣很耗電。"},{"w":"appliance","p":"n.","d":"a machine used in the home, like a washing machine","c":"家電；器具","s":"Turn off all electrical appliances before leaving for a long trip.","t":"長途旅行前請關掉所有電器。"},{"w":"applicant","p":"n.","d":"a person who applies for a job or school","c":"申請人；應徵者","s":"More than two hundred applicants applied for only five jobs.","t":"超過兩百名應徵者應徵僅五個職缺。"},{"w":"application","p":"n.","d":"a formal request; a computer program","c":"申請（書）；應用程式","s":"Please send your application before the end of March.","t":"請在三月底前寄出你的申請書。"},{"w":"conscious","p":"adj.","d":"awake; aware of something","c":"有意識的；察覺到的","s":"More people are becoming conscious of the need to save energy.","t":"越來越多人意識到節能的必要。"},{"w":"conscience","p":"n.","d":"the feeling that tells you right from wrong","c":"良心","s":"He felt a guilty conscience after lying to his friend.","t":"對朋友說謊後，他良心不安。"},{"w":"conscientious","p":"adj.","d":"careful and working hard to do things right","c":"認真盡責的","s":"She is a conscientious student who never misses a deadline.","t":"她是個認真盡責的學生，從不錯過截止日。"},{"w":"describe","p":"v.","d":"to say what someone or something is like","c":"描述；形容","s":"Can you describe the man who took your bag?","t":"你能描述一下拿走你包包的男子嗎？"},{"w":"subscribe","p":"v.","d":"to pay to receive something regularly; to sign up","c":"訂閱；訂購","s":"I subscribe to an English news podcast to improve my listening.","t":"我訂閱一個英語新聞 podcast 來加強聽力。"},{"w":"prescribe","p":"v.","d":"to say what medicine or treatment a patient should have","c":"開（藥方）；規定","s":"The doctor prescribed some medicine for my cough.","t":"醫生開了一些止咳的藥給我。"},{"w":"dictate","p":"v.","d":"to say words for someone to write down; to give orders","c":"口述；命令；支配","s":"The teacher dictated ten sentences, and we wrote them down.","t":"老師口述十個句子，我們把它們寫下來。"},{"w":"dedicate","p":"v.","d":"to give your time or energy to something","c":"奉獻；致力","s":"She dedicated her life to helping homeless children.","t":"她一生致力幫助無家可歸的孩子。"},{"w":"indicate","p":"v.","d":"to show or point out","c":"指出；顯示","s":"The report indicates that more teenagers are reading e-books.","t":"報告顯示更多青少年在讀電子書。"},{"w":"distinct","p":"adj.","d":"clearly different or easy to notice","c":"明顯的；截然不同的","s":"The two kinds of tea look the same but have distinct flavors.","t":"這兩種茶看起來一樣，但風味截然不同。"},{"w":"extinct","p":"adj.","d":"no longer existing","c":"滅絕的；（火山）死的","s":"Dinosaurs became extinct about sixty-six million years ago.","t":"恐龍大約在六千六百萬年前滅絕。"},{"w":"instinct","p":"n.","d":"a natural way of behaving that you do not learn","c":"本能；直覺","s":"Birds build nests by instinct; no one teaches them how.","t":"鳥築巢靠的是本能，沒有人教牠們。"}]},{"unit":12,"theme":"motion / notion / lotion；president / resident / precedent；refuse / refuge / refute…","cards":[{"w":"motion","p":"n.","d":"movement; a formal suggestion at a meeting","c":"動作；運動；提案","s":"The old film was shown in slow motion so we could see every step of the dancer.","t":"那部老影片用慢動作播放，讓我們看清舞者的每一步。"},{"w":"notion","p":"n.","d":"an idea or belief","c":"概念；想法","s":"The notion that girls are bad at math has been proven wrong many times.","t":"女生數學不好的觀念已被證明錯誤很多次。"},{"w":"lotion","p":"n.","d":"a liquid cream you put on your skin","c":"乳液","s":"Put on some sun lotion before you go to the beach, or you'll get burned.","t":"去海邊前擦點防曬乳，不然會曬傷。"},{"w":"president","p":"n.","d":"the leader of a country or organization","c":"總統；總裁；會長","s":"The president gave a speech about the economy on national television.","t":"總統在全國電視上發表了關於經濟的演說。"},{"w":"resident","p":"n.","d":"a person who lives in a place","c":"居民；住戶","s":"Local residents complained about the noise from the new night market.","t":"當地居民抱怨新夜市的噪音。"},{"w":"precedent","p":"n.","d":"an earlier event used as an example for later ones","c":"先例；前例","s":"The court's decision set a precedent for similar cases in the future.","t":"法院的判決為日後類似案件立下先例。"},{"w":"refuse","p":"v.","d":"to say you will not do or accept something","c":"拒絕","s":"He refused to give up, even after failing the driving test three times.","t":"即使駕照考三次都沒過，他仍拒絕放棄。"},{"w":"refuge","p":"n.","d":"a place that gives protection from danger","c":"避難所；庇護","s":"During the storm, the hikers took refuge in an old cabin.","t":"暴風雨中，登山客在一間舊小屋避難。"},{"w":"refute","p":"v.","d":"to prove that a statement is wrong","c":"反駁；駁斥","s":"The scientist used new data to refute the old theory.","t":"這位科學家用新資料駁斥了舊理論。"},{"w":"remain","p":"v.","d":"to stay in the same place or condition","c":"保持；留下；剩下","s":"Please remain in your seats until the plane has completely stopped.","t":"請在飛機完全停妥前留在座位上。"},{"w":"retain","p":"v.","d":"to keep something","c":"保留；保持","s":"Clay pots retain heat well, so the soup stays hot for a long time.","t":"陶鍋保溫效果好，所以湯能長時間保持熱度。"},{"w":"detain","p":"v.","d":"to officially keep someone and not let them leave","c":"拘留；扣留","s":"The police detained two men for questioning after the robbery.","t":"搶案發生後，警方拘留兩名男子進行訊問。"},{"w":"version","p":"n.","d":"a form of something that is a little different","c":"版本","s":"Have you downloaded the new version of the app?","t":"你下載了這個應用程式的新版本嗎？"},{"w":"versus","p":"prep.","d":"against (vs.)","c":"對抗；與…相對","s":"Tonight's game is Taiwan versus Japan.","t":"今晚的比賽是台灣對日本。"},{"w":"verse","p":"n.","d":"poetry; part of a song","c":"詩句；韻文；歌的段落","s":"The song has three verses and a chorus.","t":"這首歌有三段主歌和一段副歌。"},{"w":"vine","p":"n.","d":"a plant that climbs walls or trees","c":"藤蔓；葡萄藤","s":"Grape vines cover the walls of the old house.","t":"葡萄藤爬滿老房子的牆。"},{"w":"wine","p":"n.","d":"an alcoholic drink made from grapes","c":"葡萄酒","s":"They ordered a bottle of red wine with dinner.","t":"他們晚餐點了一瓶紅酒。"},{"w":"whine","p":"v.","d":"to complain in an annoying voice","c":"抱怨；發牢騷；哀鳴","s":"Stop whining and finish your homework.","t":"別再抱怨了，快寫完功課。"},{"w":"bride","p":"n.","d":"a woman on her wedding day","c":"新娘","s":"The bride walked down the aisle while all the guests stood and smiled.","t":"新娘走過紅毯時，所有賓客都站起來微笑。"},{"w":"bribe","p":"n./v.","d":"money or a gift given to get someone to do something dishonest","c":"賄賂","s":"The official was arrested for accepting a bribe from a construction company.","t":"這名官員因收受建設公司的賄賂而被捕。"},{"w":"corporation","p":"n.","d":"a large company","c":"公司；企業","s":"The corporation employs more than ten thousand people around the world.","t":"這家公司在全球僱用了超過一萬名員工。"},{"w":"cooperation","p":"n.","d":"working together to achieve something","c":"合作","s":"Thanks to the cooperation of all the residents, the park is clean again.","t":"多虧所有居民的合作，公園又恢復乾淨了。"},{"w":"detect","p":"v.","d":"to notice or discover something hard to see","c":"偵測；察覺","s":"The smoke alarm can detect even a small fire and warn the family in time.","t":"煙霧警報器即使是小火也能偵測到，及時警告家人。"},{"w":"defect","p":"n.","d":"a fault or problem in something","c":"缺陷；瑕疵","s":"The company called back thousands of cars because of a defect in the brakes.","t":"這家公司因煞車有缺陷而召回數千輛車。"},{"w":"disclose","p":"v.","d":"to make known something that was secret","c":"揭露；透露","s":"The company refused to disclose how much it paid the famous actor.","t":"公司拒絕透露付給那位名演員多少錢。"},{"w":"enclose","p":"v.","d":"to put something inside an envelope; to surround","c":"隨信附上；圍住","s":"I have enclosed a copy of my report card with this letter.","t":"我在這封信中附上一份成績單影本。"}]},{"unit":13,"theme":"dispose / expose / impose / oppose；dissolve / resolve；eloquent / elegant…","cards":[{"w":"dispose","p":"v.","d":"to get rid of (dispose of)","c":"處理掉；丟棄","s":"Please dispose of used batteries in the special box near the door.","t":"請將用過的電池丟到門口旁的專用盒裡。"},{"w":"expose","p":"v.","d":"to leave uncovered; to make something secret known","c":"暴露；揭發","s":"Don't expose your skin to strong sunlight for too long.","t":"別讓皮膚在強光下曝曬太久。"},{"w":"impose","p":"v.","d":"to force a rule, tax, or idea on someone","c":"強加；徵（稅）","s":"The government imposed a new tax on plastic bags.","t":"政府對塑膠袋徵收新稅。"},{"w":"oppose","p":"v.","d":"to disagree with and try to stop","c":"反對","s":"Many residents oppose the plan to build a factory near the school.","t":"許多居民反對在學校附近蓋工廠的計畫。"},{"w":"dissolve","p":"v.","d":"to mix into a liquid and disappear; to end officially","c":"溶解；解散","s":"Stir the tea until the sugar completely dissolves.","t":"攪拌茶直到糖完全溶解。"},{"w":"resolve","p":"v./n.","d":"to solve a problem; to decide firmly","c":"解決；決心","s":"The two countries resolved their dispute through peaceful talks.","t":"兩國透過和平談判解決了爭端。"},{"w":"eloquent","p":"adj.","d":"able to speak or write well and persuasively","c":"口才流利的；有說服力的","s":"The eloquent speaker moved the whole audience to tears.","t":"這位口才出眾的講者讓全場觀眾感動落淚。"},{"w":"elegant","p":"adj.","d":"graceful and attractive","c":"優雅的；高雅的","s":"She wore an elegant black dress to the dinner party.","t":"她穿了一件優雅的黑色洋裝參加晚宴。"},{"w":"ethic","p":"n.","d":"a set of moral principles","c":"倫理；道德規範","s":"Her strong work ethic made her the best employee in the company.","t":"她強烈的工作倫理讓她成為公司最優秀的員工。"},{"w":"ethnic","p":"adj.","d":"related to a group of people with a shared culture or origin","c":"種族的；民族的","s":"Taiwan has many ethnic groups, each with its own language and festivals.","t":"台灣有許多族群，各有自己的語言和節慶。"},{"w":"hammer","p":"n./v.","d":"a tool for hitting nails","c":"鐵鎚；敲打","s":"He used a hammer to fix the broken chair.","t":"他用鐵鎚修好壞掉的椅子。"},{"w":"hamper","p":"v.","d":"to make it difficult for someone to do something","c":"妨礙；阻礙","s":"Heavy rain hampered the rescue work after the earthquake.","t":"大雨妨礙了地震後的救援工作。"},{"w":"immense","p":"adj.","d":"extremely large","c":"巨大的；廣大的","s":"The new airport was built at an immense cost.","t":"新機場花了巨額成本興建。"},{"w":"intense","p":"adj.","d":"very strong or extreme","c":"強烈的；激烈的","s":"The intense heat made it hard to sleep at night.","t":"酷熱讓人晚上難以入睡。"},{"w":"liable","p":"adj.","d":"legally responsible; likely to do something","c":"有（法律）責任的；易於…的","s":"Drivers are liable for any damage they cause to other cars.","t":"駕駛人須為其對他車造成的損害負責。"},{"w":"reliable","p":"adj.","d":"able to be trusted","c":"可靠的","s":"We need a reliable car for the long trip around the island.","t":"環島長途旅行我們需要一台可靠的車。"},{"w":"reign","p":"n./v.","d":"the time a king or queen rules; to rule","c":"統治（期間）","s":"Queen Elizabeth II's reign lasted for seventy years.","t":"伊莉莎白二世女王在位長達七十年。"},{"w":"rain","p":"n./v.","d":"water that falls from clouds","c":"雨；下雨","s":"It rained all weekend, so we stayed home and watched movies.","t":"整個週末都在下雨，我們就待在家看電影。"},{"w":"rein","p":"n.","d":"a long strap used to control a horse","c":"韁繩；控制","s":"She pulled on the reins to make the horse slow down.","t":"她拉韁繩讓馬放慢速度。"},{"w":"restrain","p":"v.","d":"to stop someone from doing something; to control","c":"克制；制止","s":"He could hardly restrain his anger when he saw the mess.","t":"看到一團亂，他幾乎控制不住怒氣。"},{"w":"restrict","p":"v.","d":"to limit the size, amount, or range","c":"限制","s":"The library restricts the number of books you can borrow to ten.","t":"圖書館限制每人最多借十本書。"},{"w":"shrub","p":"n.","d":"a small bush","c":"灌木","s":"The gardener planted a row of shrubs along the fence.","t":"園丁沿著圍籬種了一排灌木。"},{"w":"scrub","p":"v.","d":"to clean by rubbing hard","c":"用力刷洗","s":"She scrubbed the kitchen floor until it was spotless.","t":"她把廚房地板刷得一塵不染。"}]},{"unit":14,"theme":"slaughter / laughter；sprinkle / sparkle；stable / staple…","cards":[{"w":"slaughter","p":"n./v.","d":"the killing of many people or animals","c":"屠殺；屠宰","s":"The slaughter of elephants for their ivory must stop.","t":"為象牙屠殺大象的行為必須停止。"},{"w":"laughter","p":"n.","d":"the sound of laughing","c":"笑聲","s":"The room was filled with laughter during the comedy show.","t":"喜劇表演時，整個房間充滿笑聲。"},{"w":"sprinkle","p":"v.","d":"to scatter small drops or pieces","c":"撒；灑","s":"Sprinkle some sugar on the strawberries.","t":"在草莓上撒點糖。"},{"w":"sparkle","p":"v./n.","d":"to shine with small flashes of light","c":"閃耀；閃爍","s":"Her eyes sparkled with excitement when she opened the gift.","t":"她打開禮物時，眼睛興奮得閃閃發亮。"},{"w":"stable","p":"adj./n.","d":"steady and not likely to change; a building for horses","c":"穩定的；馬廄","s":"After weeks in the hospital, the patient's condition is finally stable.","t":"住院數週後，病人的狀況終於穩定下來。"},{"w":"staple","p":"n./adj.","d":"a basic food or product; a small wire used to join papers","c":"主食；主要產品；訂書針","s":"Rice is a staple food for most people in Taiwan and Japan.","t":"米飯是台灣和日本大多數人的主食。"},{"w":"stray","p":"adj./v.","d":"lost, without a home; to move away from the right path","c":"流浪的；走失","s":"The shelter takes care of stray cats and dogs.","t":"收容所照顧流浪貓狗。"},{"w":"straw","p":"n.","d":"dried stems of plants; a thin tube for drinking","c":"稻草；吸管","s":"Many shops no longer give out plastic straws.","t":"許多店家不再提供塑膠吸管。"},{"w":"tackle","p":"v.","d":"to deal with a problem; to stop a player","c":"處理；擒抱","s":"The city must tackle the problem of air pollution.","t":"市政府必須處理空污問題。"},{"w":"tickle","p":"v.","d":"to touch someone lightly to make them laugh","c":"搔癢","s":"My father tickled the baby until she laughed.","t":"爸爸搔寶寶癢，直到她笑出來。"},{"w":"vain","p":"adj.","d":"without success; too proud of your looks","c":"徒勞的；自負的","s":"They tried in vain to save the old tree, but the storm knocked it down.","t":"他們試圖救那棵老樹卻徒勞無功，暴風雨還是把它吹倒了。"},{"w":"vein","p":"n.","d":"a tube that carries blood to the heart; a line in a leaf or rock","c":"靜脈；葉脈；礦脈","s":"The nurse found a vein in my arm and took a small amount of blood.","t":"護理師在我手臂上找到靜脈，抽了少量血。"},{"w":"consent","p":"n./v.","d":"permission","c":"同意；允許","s":"Students under eighteen need their parents' consent to go on the trip.","t":"未滿十八歲學生參加旅行需家長同意。"},{"w":"content","p":"n./adj.","d":"what is inside something; happy and satisfied","c":"內容；滿足的","s":"He is content with a simple life in the countryside.","t":"他滿足於鄉下簡單的生活。"},{"w":"consensus","p":"n.","d":"general agreement among a group","c":"共識","s":"After two hours of discussion, the team finally reached a consensus.","t":"經過兩小時討論，團隊終於達成共識。"},{"w":"convict","p":"v./n.","d":"to officially find someone guilty; a prisoner","c":"定罪；罪犯","s":"The man was convicted of stealing cars and sent to prison.","t":"這名男子被判竊車罪入獄。"},{"w":"convince","p":"v.","d":"to make someone believe something","c":"說服；使相信","s":"She convinced her parents that studying abroad was a good idea.","t":"她讓父母相信出國留學是個好主意。"},{"w":"convert","p":"v.","d":"to change into a different form","c":"轉換；改變信仰","s":"The old factory was converted into a popular art center.","t":"這座舊工廠被改建成熱門的藝術中心。"},{"w":"distract","p":"v.","d":"to take someone's attention away","c":"使分心","s":"The noise from the street distracted me while I was studying.","t":"街上的噪音讓我讀書時分心。"},{"w":"extract","p":"v./n.","d":"to take out or pull out; a short part of a text","c":"提取；拔出；摘錄","s":"The dentist extracted two of my teeth last week.","t":"牙醫上週拔了我兩顆牙。"},{"w":"attract","p":"v.","d":"to make someone or something come near or be interested","c":"吸引","s":"The light attracted hundreds of insects.","t":"燈光吸引了數百隻昆蟲。"},{"w":"mental","p":"adj.","d":"related to the mind","c":"心理的；精神的","s":"Getting enough sleep is important for both your physical and mental health.","t":"充足睡眠對身體和心理健康都很重要。"},{"w":"rental","p":"n./adj.","d":"the act of renting something; for rent","c":"租賃（的）；租金","s":"We picked up our rental car at the airport and drove straight to the beach.","t":"我們在機場取了租來的車，直接開到海邊。"},{"w":"dental","p":"adj.","d":"related to the teeth","c":"牙齒的","s":"Regular dental checkups can find small problems before they become painful.","t":"定期牙齒檢查能在小問題變痛之前就發現。"}]},{"unit":15,"theme":"sequence / consequence / subsequent；strive / stride / stripe；villa / villain / village…","cards":[{"w":"sequence","p":"n.","d":"the order in which things happen","c":"順序；連續","s":"Put the pictures in the correct sequence to tell the story.","t":"把圖片按正確順序排好來說故事。"},{"w":"consequence","p":"n.","d":"a result, often a bad one","c":"後果；結果","s":"If you break the rules, you must accept the consequences.","t":"如果你違反規定，就必須承擔後果。"},{"w":"subsequent","p":"adj.","d":"coming after something else","c":"隨後的；後來的","s":"The first test was easy, but subsequent tests became much harder.","t":"第一次考試很簡單，但之後的考試變得難得多。"},{"w":"strive","p":"v.","d":"to try very hard to achieve something","c":"努力；奮鬥","s":"Our school strives to give every student a chance to discover their talents.","t":"我們學校努力讓每位學生都有機會發現自己的才能。"},{"w":"stride","p":"v./n.","d":"to walk with long steps; a long step; progress","c":"大步走；跨步；進展","s":"With his long legs, the basketball player can stride across the court in just a few steps.","t":"這位籃球員腿很長，只要幾步就能大步跨過球場。"},{"w":"stripe","p":"n.","d":"a long line of color","c":"條紋","s":"A zebra's black and white stripes may help keep insects away.","t":"斑馬的黑白條紋可能有助於驅趕昆蟲。"},{"w":"villa","p":"n.","d":"a large house, often for holidays","c":"別墅","s":"They rented a villa by the sea for the summer.","t":"他們在海邊租了一棟別墅過暑假。"},{"w":"villain","p":"n.","d":"a bad person in a story","c":"壞人；反派","s":"The villain in the movie wants to destroy the city.","t":"電影中的反派想毀滅這座城市。"},{"w":"village","p":"n.","d":"a small town in the countryside","c":"村莊","s":"My grandparents live in a quiet village near the mountains.","t":"我祖父母住在山邊一個寧靜的村莊。"},{"w":"choir","p":"n.","d":"a group of people who sing together","c":"合唱團；唱詩班","s":"She sings in the school choir, and they practice every Wednesday.","t":"她參加學校合唱團，每週三練唱。"},{"w":"chore","p":"n.","d":"a regular job you do at home, such as washing dishes","c":"家事；雜務","s":"Doing the laundry is the chore I hate the most.","t":"洗衣服是我最討厭的家事。"},{"w":"chord","p":"n.","d":"three or more musical notes played together","c":"和弦","s":"He learned to play three simple chords on the guitar in one afternoon.","t":"他一個下午就學會在吉他上彈三個簡單的和弦。"},{"w":"cord","p":"n.","d":"a thin rope or an electric wire","c":"細繩；電線","s":"Be careful not to trip over the cord of the vacuum cleaner.","t":"小心別被吸塵器的電線絆倒。"},{"w":"despise","p":"v.","d":"to hate and have no respect for","c":"鄙視；看不起","s":"She despises people who are rude to waiters.","t":"她鄙視對服務生無禮的人。"},{"w":"despite","p":"prep.","d":"although; in spite of","c":"儘管","s":"Despite the bad weather, the concert went on as planned.","t":"儘管天氣不好，演唱會仍照計畫進行。"},{"w":"despair","p":"n./v.","d":"the feeling of having no hope","c":"絕望","s":"He was in despair after failing the exam for the third time.","t":"第三次考試失敗後，他陷入絕望。"},{"w":"desperate","p":"adj.","d":"without hope; willing to do anything to get something","c":"絕望的；拚命的","s":"After days without food, the lost hikers were desperate for help.","t":"幾天沒吃東西後，迷路的登山客急切地需要救援。"},{"w":"statue","p":"n.","d":"a figure of a person or animal made of stone or metal","c":"雕像","s":"Tourists take photos in front of the bronze statue in the town square.","t":"遊客在城鎮廣場的銅像前拍照。"},{"w":"status","p":"n.","d":"a person's social or professional position; condition","c":"地位；身分；狀態","s":"In the past, owning a car was a sign of high social status.","t":"過去擁有汽車是社會地位高的象徵。"},{"w":"statute","p":"n.","d":"a written law","c":"法令；法規","s":"The new statute makes it illegal to use a phone while driving.","t":"新法令規定開車時使用手機屬違法。"},{"w":"stature","p":"n.","d":"height; reputation earned from achievement","c":"身高；聲望","s":"The scientist's stature grew after she won an international prize.","t":"這位科學家獲得國際獎項後聲望大增。"},{"w":"access","p":"n./v.","d":"the right or chance to use or enter something","c":"使用權；通道；進入","s":"Every student has free access to the school's online library.","t":"每位學生都能免費使用學校的線上圖書館。"},{"w":"excess","p":"n./adj.","d":"an amount that is more than needed","c":"過量；超額","s":"Eating sugar in excess can lead to health problems.","t":"攝取過量的糖可能導致健康問題。"},{"w":"attain","p":"v.","d":"to reach or achieve a goal after effort","c":"達到；獲得","s":"She attained her goal of running a full marathon in under four hours.","t":"她達成了在四小時內跑完全馬的目標。"},{"w":"obtain","p":"v.","d":"to get something","c":"獲得；取得","s":"You must obtain permission from your parents before joining the trip.","t":"參加旅行前必須取得父母同意。"},{"w":"concede","p":"v.","d":"to admit something is true; to accept defeat","c":"承認；讓步","s":"After a long argument, he finally conceded that he was wrong.","t":"爭論許久後，他終於承認自己錯了。"},{"w":"conceive","p":"v.","d":"to form an idea in your mind; to become pregnant","c":"構想；想像；懷孕","s":"It is hard to conceive of life without smartphones today.","t":"很難想像現在沒有智慧型手機的生活。"},{"w":"conceal","p":"v.","d":"to hide","c":"隱藏；隱瞞","s":"She tried to conceal her disappointment with a smile.","t":"她試著用微笑掩飾失望。"},{"w":"drought","p":"n.","d":"a long period without rain","c":"乾旱","s":"The long drought destroyed most of the rice in the area.","t":"長期乾旱毀了這地區大部分的稻作。"},{"w":"draught","p":"n.","d":"(British) a flow of cold air in a room","c":"冷風；穿堂風（英式拼法）","s":"Close the door; there's a cold draught coming in.","t":"關上門，有冷風灌進來。"},{"w":"draft","p":"n./v.","d":"a first version of writing; cold air (US)","c":"草稿；草擬","s":"Please hand in the first draft of your essay by Friday.","t":"請在週五前交作文初稿。"}]},{"unit":16,"theme":"erupt / disrupt / corrupt / abrupt；evacuate / evaluate；evolve / involve / revolve…","cards":[{"w":"erupt","p":"v.","d":"to burst out suddenly, like a volcano","c":"爆發；噴發","s":"The volcano erupted, sending ash high into the sky.","t":"火山爆發，火山灰衝上高空。"},{"w":"disrupt","p":"v.","d":"to stop something from continuing normally","c":"擾亂；打斷","s":"The typhoon disrupted train services across the island.","t":"颱風打亂了全島的火車班次。"},{"w":"corrupt","p":"adj./v.","d":"dishonest, especially by taking money","c":"腐敗的；貪污的","s":"The corrupt officials took money from companies in exchange for contracts.","t":"腐敗的官員收取企業金錢以換取合約。"},{"w":"abrupt","p":"adj.","d":"sudden and unexpected; rude in manner","c":"突然的；唐突的","s":"The bus came to an abrupt stop, and everyone fell forward.","t":"公車突然緊急煞車，大家都往前倒。"},{"w":"evacuate","p":"v.","d":"to move people away from a dangerous place","c":"撤離；疏散","s":"Thousands of people were evacuated before the typhoon hit the coast.","t":"颱風登陸前數千人被撤離。"},{"w":"evaluate","p":"v.","d":"to judge how good or useful something is","c":"評估；評價","s":"Teachers evaluate students not only by tests but also by projects.","t":"老師評量學生不只靠考試，還看專題。"},{"w":"evolve","p":"v.","d":"to develop gradually","c":"演化；逐步發展","s":"The small family shop has evolved into a large company over fifty years.","t":"五十年來，這家家庭小店逐步發展成大公司。"},{"w":"involve","p":"v.","d":"to include as a necessary part; to take part","c":"牽涉；包含；使參與","s":"The job involves a lot of travel, so he is often away from home.","t":"這份工作需要經常出差，所以他常不在家。"},{"w":"revolve","p":"v.","d":"to move in a circle around something","c":"旋轉；圍繞","s":"The Earth revolves around the sun once a year.","t":"地球每年繞太陽公轉一圈。"},{"w":"illuminate","p":"v.","d":"to light up; to make clear","c":"照亮；闡明","s":"Colorful lanterns illuminated the streets during the festival.","t":"節慶期間，彩色燈籠照亮了街道。"},{"w":"eliminate","p":"v.","d":"to remove or get rid of","c":"消除；淘汰","s":"Our team was eliminated in the first round.","t":"我們隊在第一輪就被淘汰了。"},{"w":"inherent","p":"adj.","d":"existing as a natural or basic part","c":"固有的；內在的","s":"There are risks inherent in every sport, so always warm up first.","t":"每項運動都有固有的風險，所以一定要先暖身。"},{"w":"inherit","p":"v.","d":"to receive money or property from someone who has died; to get a quality from parents","c":"繼承；遺傳","s":"He inherited his grandfather's house and his love of music.","t":"他繼承了祖父的房子，也遺傳了祖父對音樂的熱愛。"},{"w":"intimate","p":"adj.","d":"very close and personal","c":"親密的；私密的","s":"Only a few intimate friends were invited to the small wedding.","t":"這場小型婚禮只邀請了幾位親密好友。"},{"w":"intimidate","p":"v.","d":"to frighten someone so they do what you want","c":"恐嚇；威脅","s":"The bigger boys tried to intimidate him into giving them his lunch money.","t":"那幾個大男孩想恐嚇他交出午餐錢。"},{"w":"irritate","p":"v.","d":"to annoy; to make skin painful","c":"激怒；刺激（皮膚）","s":"His habit of tapping his pen irritates everyone in the classroom.","t":"他敲筆的習慣讓教室裡每個人都很煩。"},{"w":"imitate","p":"v.","d":"to copy someone's actions or voice","c":"模仿","s":"Parrots can imitate human voices very well.","t":"鸚鵡很會模仿人的聲音。"},{"w":"moral","p":"adj./n.","d":"about right and wrong; a lesson from a story","c":"道德的；寓意","s":"The moral of the story is that honesty is the best policy.","t":"這故事的寓意是誠實為上策。"},{"w":"morale","p":"n.","d":"the confidence and spirit of a group","c":"士氣","s":"The team's morale was high after three wins in a row.","t":"連贏三場後，球隊士氣高昂。"},{"w":"mortal","p":"adj.","d":"certain to die; causing death","c":"會死的；致命的","s":"All humans are mortal.","t":"人皆難免一死。"},{"w":"potent","p":"adj.","d":"very strong or powerful","c":"強效的；有力的","s":"This medicine is very potent, so take only one pill a day.","t":"這藥效很強，所以一天只吃一顆。"},{"w":"potential","p":"adj./n.","d":"possible in the future; ability that may develop","c":"潛在的；潛力","s":"The coach believes the young player has the potential to become a star.","t":"教練相信這位年輕球員有成為明星的潛力。"},{"w":"precise","p":"adj.","d":"exact and accurate","c":"精確的；準確的","s":"Please give me the precise time the accident happened.","t":"請告訴我事故發生的確切時間。"},{"w":"concise","p":"adj.","d":"short and clear","c":"簡潔的；簡明的","s":"Your summary should be concise, no more than fifty words.","t":"你的摘要要簡潔，不超過五十字。"}]},{"unit":17,"theme":"torment / torrent / torture；via / visa；casual / causal / casualty…","cards":[{"w":"torment","p":"n./v.","d":"great mental or physical pain","c":"折磨；痛苦","s":"He was in torment while waiting for the test results.","t":"等待檢查結果時，他飽受煎熬。"},{"w":"torrent","p":"n.","d":"a fast, strong flow of water; a large amount","c":"急流；洪流；一連串","s":"After the storm, the small stream became a torrent.","t":"暴風雨後，小溪變成了急流。"},{"w":"torture","p":"n./v.","d":"causing great pain on purpose","c":"酷刑；折磨","s":"Waiting in line for three hours was torture.","t":"排隊三小時簡直是折磨。"},{"w":"via","p":"prep.","d":"by way of; using","c":"經由；透過","s":"We flew to London via Dubai.","t":"我們經杜拜飛往倫敦。"},{"w":"visa","p":"n.","d":"a document that allows you to enter a country","c":"簽證","s":"You need a visa to study in the United States.","t":"你需要簽證才能去美國留學。"},{"w":"casual","p":"adj.","d":"relaxed and informal; not planned","c":"隨意的；休閒的","s":"You can wear casual clothes on Friday, but please wear a suit to the meeting on Monday.","t":"週五可以穿休閒服，但週一開會請穿西裝。"},{"w":"causal","p":"adj.","d":"showing that one thing causes another","c":"因果的","s":"Scientists have found a causal link between smoking and lung disease.","t":"科學家已發現吸菸和肺病之間有因果關係。"},{"w":"casualty","p":"n.","d":"a person hurt or killed in an accident or war","c":"傷亡者","s":"Luckily, there were no casualties when the old bridge suddenly fell into the river.","t":"幸運的是，那座老橋突然塌入河中時並無傷亡。"},{"w":"exhibit","p":"v./n.","d":"to show in public","c":"展示；展出","s":"The museum exhibits paintings by local artists.","t":"博物館展出本地藝術家的畫作。"},{"w":"prohibit","p":"v.","d":"to officially forbid","c":"禁止","s":"Smoking is prohibited in all public buildings.","t":"所有公共建築內都禁止吸菸。"},{"w":"inhibit","p":"v.","d":"to slow down or prevent; to make someone too shy to act","c":"抑制；使拘束","s":"Fear of making mistakes can inhibit students from speaking English.","t":"害怕犯錯會讓學生不敢開口說英文。"},{"w":"lightning","p":"n.","d":"the flash of light in the sky during a storm","c":"閃電","s":"Never stand under a tree during a storm, because lightning often hits tall objects.","t":"暴風雨時千萬別站在樹下，因為閃電常擊中高的物體。"},{"w":"lightening","p":"v.","d":"(-ing form of lighten) making lighter or brighter","c":"正在變亮；正在減輕","s":"The sky was lightening in the east as the fishermen pushed their boats into the sea.","t":"漁夫把船推入海中時，東方的天空漸漸亮起來。"},{"w":"lighten","p":"v.","d":"to make something lighter in weight or brighter","c":"減輕；使明亮","s":"Hiring two more workers will lighten the workload for everyone in the office.","t":"再請兩位員工能減輕辦公室每個人的工作量。"},{"w":"attitude","p":"n.","d":"the way you think or feel about something","c":"態度","s":"A positive attitude can help you learn faster.","t":"積極的態度能幫助你學得更快。"},{"w":"altitude","p":"n.","d":"height above sea level","c":"海拔；高度","s":"The plane is flying at an altitude of ten thousand meters.","t":"飛機正在海拔一萬公尺的高度飛行。"},{"w":"latitude","p":"n.","d":"distance north or south of the equator; freedom to choose","c":"緯度；（行動的）自由度","s":"Taiwan lies at a latitude of about twenty-three degrees north.","t":"台灣位在北緯約二十三度。"},{"w":"longitude","p":"n.","d":"distance east or west of a line through Greenwich","c":"經度","s":"Sailors used clocks to work out their longitude at sea.","t":"水手們利用時鐘在海上推算經度。"},{"w":"decent","p":"adj.","d":"good enough; honest and polite","c":"像樣的；正派的","s":"After months of looking, my brother finally found a decent job with a fair salary.","t":"找了幾個月後，我哥哥終於找到一份薪水合理的像樣工作。"},{"w":"descent","p":"n.","d":"a movement downward; family origin","c":"下降；血統","s":"The plane began its descent, so the passengers fastened their seat belts.","t":"飛機開始下降，所以乘客們繫好了安全帶。"},{"w":"descend","p":"v.","d":"to move down","c":"下降；走下","s":"The hikers had to descend the mountain quickly because a storm was coming.","t":"暴風雨即將來臨，登山客必須迅速下山。"},{"w":"exclaim","p":"v.","d":"to say something suddenly because of surprise","c":"驚呼；呼喊","s":"\"Look, it's snowing!\" the children exclaimed.","t":"「看，下雪了！」孩子們驚呼。"},{"w":"proclaim","p":"v.","d":"to announce officially and publicly","c":"宣布；宣告","s":"The king proclaimed a national holiday to celebrate the victory.","t":"國王宣布全國放假慶祝勝利。"},{"w":"acclaim","p":"n./v.","d":"public praise","c":"稱讚；喝采","s":"The movie received wide acclaim from both critics and audiences.","t":"這部電影廣受影評人與觀眾好評。"},{"w":"expire","p":"v.","d":"to come to an end; to stop being valid","c":"到期；失效","s":"My passport expires next month, so I need to renew it before the trip.","t":"我的護照下個月到期，所以出發前得換新。"},{"w":"inspire","p":"v.","d":"to give someone the wish or ideas to do something","c":"啟發；激勵","s":"Her story inspired many young people to become volunteers.","t":"她的故事激勵許多年輕人成為志工。"},{"w":"aspire","p":"v.","d":"to have a strong wish to achieve something","c":"渴望；立志","s":"He aspires to become a pilot, so he studies physics very hard.","t":"他立志當飛行員，所以很認真讀物理。"},{"w":"fiction","p":"n.","d":"stories about imaginary people and events","c":"小說；虛構","s":"She prefers science fiction to history books.","t":"比起歷史書，她更喜歡科幻小說。"},{"w":"friction","p":"n.","d":"rubbing of one surface against another; disagreement","c":"摩擦；不和","s":"There has been some friction between the two teams since the last game.","t":"自上次比賽後，兩隊之間就有些摩擦。"},{"w":"faction","p":"n.","d":"a small group within a larger group that disagrees with others","c":"派系；黨派","s":"The party split into two factions over the new tax plan.","t":"該黨因新稅制計畫分裂成兩個派系。"}]},{"unit":18,"theme":"literal / literary / literate；perspective / prospective / prospect；trifle / trivial / rifle…","cards":[{"w":"literal","p":"adj.","d":"using the basic meaning of a word","c":"字面的；逐字的","s":"The literal meaning of \"break a leg\" is very different from what it really means.","t":"「break a leg」的字面意思和它的真正意思差很多。"},{"w":"literary","p":"adj.","d":"related to literature","c":"文學的","s":"She won a literary prize for her first novel.","t":"她的第一部小說獲得文學獎。"},{"w":"literate","p":"adj.","d":"able to read and write; knowing a lot about a subject","c":"識字的；有學問的","s":"Today, young people need to be computer literate.","t":"現在年輕人需要具備電腦能力。"},{"w":"perspective","p":"n.","d":"a way of thinking about something","c":"觀點；看法","s":"Traveling abroad gave me a new perspective on life.","t":"出國旅行讓我對人生有了新的看法。"},{"w":"prospective","p":"adj.","d":"expected to be something in the future","c":"預期的；未來的","s":"The school held an open day for prospective students and their parents.","t":"學校為未來的新生及家長舉辦開放日。"},{"w":"prospect","p":"n.","d":"the possibility that something will happen","c":"前景；可能性","s":"The prospect of a long holiday made everyone happy.","t":"即將放長假讓大家都很開心。"},{"w":"trifle","p":"n.","d":"something unimportant; a little","c":"瑣事；少許","s":"Don't get upset over such a trifle.","t":"別為這種小事生氣。"},{"w":"trivial","p":"adj.","d":"not important","c":"瑣碎的；不重要的","s":"Don't waste time on trivial details.","t":"別把時間浪費在瑣碎的細節上。"},{"w":"rifle","p":"n.","d":"a long gun","c":"步槍；來福槍","s":"The soldier cleaned his rifle every night.","t":"那名士兵每晚清理他的步槍。"},{"w":"anonymous","p":"adj.","d":"with a name that is not known","c":"匿名的","s":"An anonymous donor gave the hospital one million dollars.","t":"一位匿名捐贈者捐給醫院一百萬元。"},{"w":"unanimous","p":"adj.","d":"agreed by everyone","c":"一致同意的","s":"The class made a unanimous decision to visit the zoo on the field trip.","t":"全班一致決定校外教學去動物園。"},{"w":"commute","p":"v./n.","d":"to travel regularly between home and work","c":"通勤","s":"My father commutes to Taipei by high-speed rail every day.","t":"我爸爸每天搭高鐵通勤到台北。"},{"w":"compute","p":"v.","d":"to calculate","c":"計算","s":"The app can compute your monthly expenses automatically.","t":"這個應用程式能自動計算你每月的開銷。"},{"w":"deprive","p":"v.","d":"to take something important away from someone","c":"剝奪；使喪失","s":"Working late every night deprives you of the sleep you need.","t":"每晚熬夜工作會剝奪你需要的睡眠。"},{"w":"derive","p":"v.","d":"to get something from a source","c":"得到；源自","s":"Many English words derive from Latin.","t":"許多英文字源自拉丁文。"},{"w":"evoke","p":"v.","d":"to bring a memory or feeling into your mind","c":"喚起；引起（回憶、情感）","s":"The smell of the rice cake evoked memories of my grandmother's kitchen.","t":"年糕的味道喚起我對奶奶廚房的回憶。"},{"w":"provoke","p":"v.","d":"to make someone angry; to cause a reaction","c":"激怒；引發","s":"His rude comment provoked a fight between the two students.","t":"他無禮的話引發兩名學生打架。"},{"w":"foul","p":"adj./n.","d":"very bad or dirty; an action against the rules","c":"惡臭的；犯規","s":"A foul smell came from the trash can that no one had emptied.","t":"那個沒人倒的垃圾桶傳出一股惡臭。"},{"w":"fowl","p":"n.","d":"birds such as chickens and ducks kept for meat or eggs","c":"家禽","s":"The farmer keeps fowl such as ducks and chickens behind the house.","t":"農夫在屋後養了鴨、雞等家禽。"},{"w":"incline","p":"v./n.","d":"to tend to think or do something; a slope","c":"傾向；斜坡","s":"I'm inclined to agree with you, but let me think about it first.","t":"我傾向同意你，但讓我先想一想。"},{"w":"decline","p":"v./n.","d":"to become less; to politely refuse","c":"下降；衰退；婉拒","s":"She declined the job offer because the salary was too low.","t":"她因薪水太低婉拒了這份工作。"},{"w":"indigenous","p":"adj.","d":"belonging naturally to a place","c":"原住民的；本土的","s":"The museum shows the culture of Taiwan's indigenous peoples.","t":"這座博物館展示台灣原住民族的文化。"},{"w":"indignant","p":"adj.","d":"angry because something is unfair","c":"憤慨的；憤憤不平的","s":"The customers were indignant when the shop refused to give them a refund.","t":"店家拒絕退款，顧客們憤憤不平。"}]},{"unit":19,"theme":"moan / mourn；predator / predecessor；premier / premiere…","cards":[{"w":"moan","p":"v./n.","d":"to make a low sound of pain; to complain","c":"呻吟；抱怨","s":"The injured player lay on the ground, moaning in pain.","t":"受傷的球員躺在地上痛苦地呻吟。"},{"w":"mourn","p":"v.","d":"to feel very sad because someone has died","c":"哀悼；悲痛","s":"The whole country mourned the death of the beloved singer.","t":"舉國哀悼這位深受喜愛的歌手辭世。"},{"w":"predator","p":"n.","d":"an animal that hunts and eats other animals","c":"掠食者；捕食者","s":"Lions are the top predators on the African grasslands.","t":"獅子是非洲草原上的頂級掠食者。"},{"w":"predecessor","p":"n.","d":"a person who had a job before someone else","c":"前任；前輩","s":"The new principal is much stricter than her predecessor.","t":"新校長比她的前任嚴格得多。"},{"w":"premier","p":"n./adj.","d":"the leader of a government; most important","c":"首相；總理；首要的","s":"The premier met the visiting president at the airport.","t":"總理在機場會見來訪的總統。"},{"w":"premiere","p":"n.","d":"the first public show of a movie or play","c":"首映；首演","s":"Fans waited for hours outside the theater for the movie premiere.","t":"粉絲在戲院外等了好幾小時參加電影首映。"},{"w":"rugged","p":"adj.","d":"rough and uneven; strong and able to last","c":"崎嶇的；堅固耐用的","s":"The rugged mountain road is closed to buses after heavy rain.","t":"大雨後，這條崎嶇的山路禁止巴士通行。"},{"w":"ragged","p":"adj.","d":"old and torn","c":"破爛的；衣衫襤褸的","s":"The boy in ragged clothes was selling flowers on the street.","t":"衣衫襤褸的男孩在街上賣花。"},{"w":"scrap","p":"n./v.","d":"a small piece; to get rid of","c":"碎片；廢料；廢棄","s":"She wrote the phone number on a scrap of paper.","t":"她把電話號碼寫在一張小紙片上。"},{"w":"scrape","p":"v.","d":"to rub with something sharp to remove or damage","c":"刮；擦傷","s":"I fell off my bike and scraped my knee on the road.","t":"我從腳踏車上摔下來，膝蓋在路上擦傷了。"},{"w":"veteran","p":"n./adj.","d":"a former soldier; a person with long experience","c":"退伍軍人；老手","s":"The veteran teacher has taught English for more than thirty years.","t":"這位資深老師教英文已超過三十年。"},{"w":"veterinarian","p":"n.","d":"a doctor for animals","c":"獸醫","s":"We took our sick cat to the veterinarian right after school.","t":"我們一放學就帶生病的貓去看獸醫。"},{"w":"vow","p":"n./v.","d":"a serious promise","c":"誓言；發誓","s":"He made a vow never to smoke again.","t":"他發誓再也不抽菸。"},{"w":"vowel","p":"n.","d":"a sound or letter such as a, e, i, o, u","c":"母音","s":"The word \"eye\" has two vowels and one consonant.","t":"eye 這個字有兩個母音和一個子音。"},{"w":"wary","p":"adj.","d":"careful because something might be dangerous","c":"小心提防的；謹慎的","s":"Be wary of strangers who ask for your personal information online.","t":"小心提防在網路上索取你個資的陌生人。"},{"w":"weary","p":"adj.","d":"very tired","c":"疲倦的；厭倦的","s":"After walking all day in the hot sun, we were weary and hungry.","t":"在大太陽下走了一整天，我們又累又餓。"},{"w":"depress","p":"v.","d":"to make someone feel sad","c":"使沮喪；使蕭條","s":"Rainy weather always depresses me.","t":"下雨天總讓我心情低落。"},{"w":"oppress","p":"v.","d":"to treat people cruelly and unfairly","c":"壓迫","s":"The cruel king oppressed his people for many years.","t":"殘暴的國王壓迫人民多年。"},{"w":"suppress","p":"v.","d":"to stop something by force; to hold back a feeling","c":"鎮壓；抑制","s":"She tried to suppress a laugh during the serious meeting.","t":"嚴肅的會議中她努力憋住笑。"},{"w":"swamp","p":"n./v.","d":"wet land; to give someone too much to deal with","c":"沼澤；使應接不暇","s":"After the holiday, I was swamped with e-mails.","t":"假期過後，我被大量郵件淹沒。"},{"w":"swarm","p":"n./v.","d":"a large group of insects or people moving together","c":"一大群；成群移動","s":"A swarm of bees flew out of the tree.","t":"一大群蜜蜂從樹上飛出來。"},{"w":"swap","p":"v./n.","d":"to exchange","c":"交換","s":"Can we swap seats? I can't see the screen.","t":"我們可以換位子嗎？我看不到螢幕。"}]},{"unit":20,"theme":"alter / altar；sober / somber；spacious / specious…","cards":[{"w":"alter","p":"v.","d":"to change","c":"改變；修改（衣服）","s":"The tailor altered my pants because they were too long.","t":"裁縫修改了我的褲子，因為太長了。"},{"w":"altar","p":"n.","d":"a holy table in a church or temple","c":"祭壇；聖壇","s":"The couple stood in front of the altar and said their vows.","t":"這對新人站在祭壇前宣誓。"},{"w":"sober","p":"adj.","d":"not drunk; serious and calm in thinking","c":"清醒的；冷靜嚴肅的","s":"He waited until he was completely sober before he drove home from the party.","t":"他等到完全清醒後才從派對開車回家。"},{"w":"somber","p":"adj.","d":"dark in color; sad and serious in mood","c":"陰暗的；憂鬱沉重的","s":"Everyone wore somber black clothes to the funeral, and nobody spoke much.","t":"大家都穿著深暗的黑衣參加喪禮，沒有人多說話。"},{"w":"spacious","p":"adj.","d":"having a lot of space","c":"寬敞的","s":"Our new apartment has a spacious living room.","t":"我們的新公寓有個寬敞的客廳。"},{"w":"specious","p":"adj.","d":"seeming right but actually wrong","c":"似是而非的；華而不實的","s":"His specious argument fooled many people at first.","t":"他似是而非的論點一開始騙了很多人。"},{"w":"stimulate","p":"v.","d":"to encourage something to grow or develop","c":"刺激；激發","s":"Lower taxes may stimulate the economy.","t":"降稅可能刺激經濟。"},{"w":"simulate","p":"v.","d":"to imitate real conditions","c":"模擬；假裝","s":"Pilots train in machines that simulate real flights.","t":"飛行員在模擬真實飛行的機器裡訓練。"},{"w":"throne","p":"n.","d":"the special chair of a king or queen; royal power","c":"王位；寶座","s":"The young prince came to the throne at the age of twelve.","t":"年輕王子十二歲就登上王位。"},{"w":"thrown","p":"v.","d":"past participle of throw","c":"被丟；被拋（throw 的過去分詞）","s":"The ball was thrown over the fence.","t":"球被丟過了圍籬。"},{"w":"vicious","p":"adj.","d":"cruel and violent","c":"兇惡的；惡毒的","s":"Lack of sleep and stress can create a vicious circle.","t":"睡眠不足和壓力可能形成惡性循環。"},{"w":"virtuous","p":"adj.","d":"morally good","c":"有德行的；品德高尚的","s":"In the old story, the virtuous girl is rewarded for her kindness.","t":"在古老的故事裡，品德高尚的女孩因善良而得到回報。"},{"w":"mediate","p":"v.","d":"to help two sides end a disagreement","c":"調解；斡旋","s":"A teacher mediated between the two students after their fight.","t":"兩名學生打架後，一位老師居中調解。"},{"w":"meditate","p":"v.","d":"to think deeply in silence, often to relax","c":"冥想；沉思","s":"She meditates for ten minutes every morning to calm her mind.","t":"她每天早上冥想十分鐘讓心情平靜。"},{"w":"notable","p":"adj.","d":"important or interesting enough to notice","c":"值得注意的；顯著的","s":"There has been a notable increase in online shopping this year.","t":"今年網購有顯著增加。"},{"w":"notorious","p":"adj.","d":"famous for something bad","c":"惡名昭彰的","s":"The road is notorious for traffic accidents.","t":"這條路以車禍頻傳而惡名昭彰。"},{"w":"nourish","p":"v.","d":"to give food needed for health and growth","c":"滋養；養育","s":"Good soil nourishes the plants and helps them grow quickly.","t":"肥沃的土壤滋養植物，幫助它們快速生長。"},{"w":"flourish","p":"v.","d":"to grow well; to be successful","c":"茂盛；繁榮；興旺","s":"Small businesses flourished after the new train station opened.","t":"新火車站啟用後，小商家蓬勃發展。"},{"w":"preside","p":"v.","d":"to be in charge of a meeting or event","c":"主持；掌管","s":"The principal presided over the graduation ceremony.","t":"校長主持了畢業典禮。"},{"w":"reside","p":"v.","d":"to live in a place","c":"居住","s":"Her family has resided in this small town for three generations.","t":"她家已在這個小鎮住了三代。"}]},{"unit":21,"theme":"savage / salvage；solitary / solitude / solidarity；stroll / scroll…","cards":[{"w":"savage","p":"adj.","d":"very violent or cruel; wild","c":"兇猛的；野蠻的","s":"The village was attacked by a savage tiger.","t":"村莊遭到一隻兇猛的老虎攻擊。"},{"w":"salvage","p":"v.","d":"to save something from being lost or destroyed","c":"搶救；打撈","s":"Workers tried to salvage what they could from the burned house.","t":"工人們盡力從燒毀的房子裡搶救東西。"},{"w":"solitary","p":"adj.","d":"alone; done alone","c":"獨自的；孤單的","s":"The old man lives a solitary life in the mountains.","t":"那位老人在山中過著獨居生活。"},{"w":"solitude","p":"n.","d":"the state of being alone, often by choice","c":"獨處；孤獨","s":"She enjoys the solitude of early morning walks.","t":"她享受清晨散步的獨處時光。"},{"w":"solidarity","p":"n.","d":"support and unity among people","c":"團結；休戚與共","s":"People wore yellow ribbons to show solidarity with the victims.","t":"人們繫上黃絲帶，表示與受害者同在。"},{"w":"stroll","p":"v./n.","d":"to walk slowly and calmly","c":"散步；閒逛","s":"We strolled along the river after dinner.","t":"晚餐後我們沿著河邊散步。"},{"w":"scroll","p":"v./n.","d":"to move text on a screen up or down; a roll of paper","c":"滑動（螢幕）；捲軸","s":"Scroll down to see the rest of the page.","t":"往下滑看頁面的其他內容。"},{"w":"vigorous","p":"adj.","d":"strong and full of energy","c":"精力充沛的；激烈的","s":"Doctors suggest thirty minutes of vigorous exercise three times a week.","t":"醫生建議每週三次、每次三十分鐘的劇烈運動。"},{"w":"rigorous","p":"adj.","d":"very strict and careful","c":"嚴格的；嚴謹的","s":"All new medicines go through rigorous testing.","t":"所有新藥都要經過嚴格測試。"},{"w":"dual","p":"adj.","d":"having two parts or uses","c":"雙重的","s":"The singer has dual citizenship, so she holds both a Taiwanese and an American passport.","t":"這位歌手有雙重國籍，持有台灣和美國護照。"},{"w":"duel","p":"n.","d":"a formal fight between two people","c":"決鬥；對決","s":"In old Western movies, the hero often wins a gun duel at the end.","t":"在老西部片中，主角常在最後贏得槍戰對決。"},{"w":"fragrant","p":"adj.","d":"having a sweet smell","c":"芳香的","s":"The garden is full of fragrant roses.","t":"花園裡滿是芳香的玫瑰。"},{"w":"flagrant","p":"adj.","d":"shockingly obvious (about something bad)","c":"明目張膽的；公然的","s":"Taking money from the fund was a flagrant abuse of power.","t":"從基金中拿錢是公然濫權。"},{"w":"imminent","p":"adj.","d":"about to happen very soon","c":"迫在眉睫的；即將發生的","s":"Dark clouds showed that a storm was imminent.","t":"烏雲顯示暴風雨即將來臨。"},{"w":"eminent","p":"adj.","d":"famous and respected","c":"卓越的；著名的","s":"An eminent scientist gave a talk at our school.","t":"一位著名的科學家到我們學校演講。"},{"w":"martial","p":"adj.","d":"related to war or fighting","c":"軍事的；武術的","s":"He has practiced martial arts such as kung fu for ten years.","t":"他練功夫等武術已十年。"},{"w":"marital","p":"adj.","d":"related to marriage","c":"婚姻的","s":"The form asks for your name, age, and marital status.","t":"這張表格要填姓名、年齡和婚姻狀況。"}]}];
